import { Droplets, AlertTriangle } from 'lucide-react'
import type { EnrichedDevice } from '../types'
import { getDeviceDisplayName } from '../lib/constants'
import { cn } from '../lib/utils'

interface ActivityPanelProps {
    safeTDSDevices: EnrichedDevice[]
    criticalTDSDevices: EnrichedDevice[]
    onDeviceClick?: (deviceId: string) => void
}

const ScrollableSection = ({
    title,
    count,
    icon: Icon,
    color,
    children
}: {
    title: string
    count: number
    icon: any
    color: string
    children: React.ReactNode
}) => (
    <div className="glass-system-parent rounded-2xl overflow-hidden border-border shadow-xl">
        <div className="flex items-center justify-between p-4">
            <div className="flex items-center gap-3">
                <div className={cn("p-2 rounded-lg", color)}>
                    <Icon className="w-4 h-4" />
                </div>
                <div className="text-left">
                    <h3 className="text-sm font-semibold text-foreground">{title}</h3>
                    <p className="text-xs text-muted-foreground">{count} device{count !== 1 ? 's' : ''}</p>
                </div>
            </div>
        </div>
        <div className="px-4 pb-4 pt-2 max-h-[300px] overflow-y-auto custom-scrollbar">
            {children}
        </div>
    </div>
)

const DeviceList = ({ 
    devices, 
    emptyMessage, 
    onDeviceClick 
}: { 
    devices: EnrichedDevice[]
    emptyMessage: string
    onDeviceClick?: (deviceId: string) => void
}) => {
    if (devices.length === 0) {
        return (
            <div className="text-sm text-muted-foreground text-center py-4">
                {emptyMessage}
            </div>
        )
    }

    return (
        <div className="space-y-1">
            {devices.map((device) => (
                <button
                    key={device.id}
                    onClick={() => onDeviceClick?.(device.id)}
                    className="w-full flex items-center justify-between p-3 rounded-lg glass-system-child hover:scale-[1.01] transition-all text-left group border-border"
                >
                    <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">
                            {getDeviceDisplayName(device)}
                        </p>
                        <p className="text-xs text-muted-foreground mt-0.5">
                            {device.latest_tds ? `${device.latest_tds.toFixed(0)} PPM` : 'No data'}
                            {device.latest_temperature && ` • ${device.latest_temperature.toFixed(1)}°C`}
                        </p>
                    </div>
                    <div className={cn(
                        "ml-2 px-2 py-1 rounded-md text-[10px] font-bold border glass-system-inset",
                        device.connectivity_status === 'online' && "text-emerald-400 border-emerald-500/20 shadow-emerald-500/10",
                        device.connectivity_status === 'offline' && "text-muted-foreground border-border"
                    )}>
                        {device.connectivity_status === 'online' ? 'Online' : 'Offline'}
                    </div>
                </button>
            ))}
        </div>
    )
}

export function ActivityPanel({
    safeTDSDevices,
    criticalTDSDevices,
    onDeviceClick
}: ActivityPanelProps) {
    return (
        <div className="space-y-4">
            <h2 className="text-base font-bold text-foreground/80 tracking-tight px-1">Recent Activity</h2>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {/* Safe TDS Section - Always Visible, Scrollable */}
                <ScrollableSection
                    title="Safe TDS"
                    count={safeTDSDevices.length}
                    icon={Droplets}
                    color="bg-emerald-500/10 text-emerald-500 border border-emerald-500/20"
                >
                    <DeviceList 
                        devices={safeTDSDevices} 
                        emptyMessage="No devices with safe TDS levels" 
                        onDeviceClick={onDeviceClick}
                    />
                </ScrollableSection>

                {/* Critical TDS Section - Always Visible, Scrollable */}
                <ScrollableSection
                    title="Critical TDS"
                    count={criticalTDSDevices.length}
                    icon={AlertTriangle}
                    color="bg-red-500/10 text-red-500 border border-red-500/20"
                >
                    <DeviceList 
                        devices={criticalTDSDevices} 
                        emptyMessage="No devices with critical TDS levels" 
                        onDeviceClick={onDeviceClick}
                    />
                </ScrollableSection>
            </div>
        </div>
    )
}

