import { useState, useEffect } from 'react'
import { collection, query as firestoreQuery, where, getDocs, limit } from 'firebase/firestore'
import { Search, Command, ArrowRight, Monitor, AlertTriangle } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { db } from '../lib/firebase'
import { useUI } from '../context/UIContext'
import { cn } from '../lib/utils'

interface SearchResult {
    id: string
    type: 'device' | 'alert' | 'nav'
    title: string
    subtitle?: string
    metadata?: any
    url?: string
}

export default function CommandPalette() {
    const [isOpen, setIsOpen] = useState(false)
    const [query, setQuery] = useState('')
    const [results, setResults] = useState<SearchResult[]>([])
    const [selectedIndex, setSelectedIndex] = useState(0)
    const navigate = useNavigate()

    const { openInspector } = useUI()

    const handleSelect = (result: SearchResult) => {
        if (result.type === 'nav' && result.url) {
            navigate(result.url)
        } else if (result.type === 'device') {
            openInspector(result.id)
        }
        setIsOpen(false)
    }

    // Shortcuts
    useEffect(() => {
        const handleDown = (e: KeyboardEvent) => {
            if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
                e.preventDefault()
                setIsOpen(prev => !prev)
            }
            if (!isOpen) return

            if (e.key === 'Escape') {
                setIsOpen(false)
            }
            if (e.key === 'ArrowDown') {
                e.preventDefault()
                setSelectedIndex(prev => (prev + 1) % results.length)
            }
            if (e.key === 'ArrowUp') {
                e.preventDefault()
                setSelectedIndex(prev => (prev - 1 + results.length) % results.length)
            }
            if (e.key === 'Enter') {
                e.preventDefault()
                if (results[selectedIndex]) {
                    handleSelect(results[selectedIndex])
                }
            }
        }
        document.addEventListener('keydown', handleDown)
        return () => document.removeEventListener('keydown', handleDown)
    }, [isOpen, results, selectedIndex, handleSelect])

    // Search Logic
    useEffect(() => {
        if (!isOpen) return

        const search = async () => {
            if (query.trim() === '') {
                setResults([
                    { id: 'nav-map', type: 'nav', title: 'Go to Map', url: '/map', subtitle: 'View geolocation' },
                    { id: 'nav-alerts', type: 'nav', title: 'Go to Alerts', url: '/alerts', subtitle: 'View system warnings' },
                    { id: 'nav-devices', type: 'nav', title: 'Go to Devices', url: '/devices', subtitle: 'Manage inventory' },
                ])
                return
            }

            try {
                // Since Firestore doesn't have a native global search RPC like PostgREST,
                // we'll perform a query on the devices collection.
                const q = firestoreQuery(
                    collection(db, 'devices'),
                    where('name', '>=', query),
                    where('name', '<=', query + '\uf8ff'),
                    limit(5)
                )

                const querySnapshot = await getDocs(q)
                const deviceResults: SearchResult[] = []

                querySnapshot.forEach((doc) => {
                    const d = doc.data() as any
                    deviceResults.push({
                        id: doc.id,
                        type: 'device',
                        title: d.name || 'Unnamed Device',
                        subtitle: d.location_name || 'No location',
                        metadata: { status: d.status }
                    })
                })

                setResults(deviceResults.length > 0 ? deviceResults : [
                    { id: 'nav-map', type: 'nav', title: 'Go to Map', url: '/map', subtitle: 'View geolocation' },
                    { id: 'nav-alerts', type: 'nav', title: 'Go to Alerts', url: '/alerts', subtitle: 'View system warnings' },
                    { id: 'nav-devices', type: 'nav', title: 'Go to Devices', url: '/devices', subtitle: 'Manage inventory' },
                ])
            } catch (e) {
                console.error('Search error:', e)
            }
        }

        const timeout = setTimeout(search, 300)
        return () => clearTimeout(timeout)
    }, [query, isOpen])

    if (!isOpen) return null

    return (
        <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[20vh] px-4">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsOpen(false)} />

            <div className={cn(
                "relative w-full max-w-xl border rounded-xl shadow-2xl overflow-hidden animate-scale-in",
                // Light mode
                "bg-white/95 border-black/10",
                // Dark mode
                "dark:bg-[#1c1c1e] dark:border-white/10"
            )}>
                {/* Search Input */}
                <div className="flex items-center px-4 py-4 border-b border-border">
                    <Search className="w-5 h-5 text-muted-foreground mr-3" />
                    <input
                        autoFocus
                        type="text"
                        placeholder="Search devices, alerts, or commands..."
                        className="bg-transparent text-foreground text-lg placeholder:text-muted-foreground/60 w-full outline-none"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                    />
                    <div className="flex gap-2">
                        <kbd className="hidden sm:inline-flex items-center gap-1 px-2 py-1 bg-accent/20 rounded text-[10px] text-muted-foreground font-mono">
                            ESC
                        </kbd>
                    </div>
                </div>

                {/* Results */}
                <div className="max-h-[60vh] overflow-y-auto p-2">
                    {results.length === 0 ? (
                        <div className="p-8 text-center text-muted-foreground text-sm">
                            No results found for "{query}"
                        </div>
                    ) : (
                        <div className="space-y-1">
                            {results.map((result, i) => (
                                <button
                                    key={result.id}
                                    onClick={() => handleSelect(result)}
                                    className={cn(
                                        "w-full flex items-center justify-between px-3 py-3 rounded-lg group transition-colors",
                                        i === selectedIndex ? 'bg-primary/20' : 'hover:bg-accent/50'
                                    )}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={cn(
                                            "p-2 rounded-md",
                                            i === selectedIndex ? 'bg-primary/20' : 'bg-accent/30'
                                        )}>
                                            {result.type === 'device' ? <Monitor className="w-4 h-4 text-foreground" /> :
                                                result.type === 'alert' ? <AlertTriangle className="w-4 h-4 text-amber-400" /> :
                                                    <Command className="w-4 h-4 text-muted-foreground" />}
                                        </div>
                                        <div className="text-left">
                                            <p className={cn(
                                                "text-sm font-medium",
                                                i === selectedIndex ? 'text-primary' : 'text-foreground'
                                            )}>
                                                {result.title}
                                            </p>
                                            {result.subtitle && (
                                                <p className={cn(
                                                    "text-xs",
                                                    i === selectedIndex ? 'text-primary/70' : 'text-muted-foreground'
                                                )}>
                                                    {result.subtitle}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                    {i === selectedIndex && <ArrowRight className="w-4 h-4 text-primary" />}
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-4 py-2 bg-accent/20 text-[10px] text-muted-foreground border-t border-border flex justify-between">
                    <span>ProTip: Search "Offline" to filter lists</span>
                    <span>EvaraTDS v1.0</span>
                </div>
            </div>
        </div>
    )
}

import { useState, useEffect } from 'react'
import { db } from '../lib/firebase'
import { collection, query, where, orderBy, limit, getDocs, doc, updateDoc, addDoc, serverTimestamp } from 'firebase/firestore'
import { type Device } from '../types'
import { getDeviceDisplayName } from '../lib/constants'
import {
    X,
    Battery,
    Wifi,
    MapPin,
    Clock,
    Activity,
    Settings,
    History,
    AlertTriangle,
    CheckCircle,
    Wrench,
    ChevronRight,
    RefreshCw
} from 'lucide-react'
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts'
import HealthTimeline from './HealthTimeline'
import ConfidenceRing from './ConfidenceRing'

// Extend Device to include optional runtime properties or mapped fields
type ModalDevice = Device & {
    device_id?: string
    battery_level?: number
    signal_strength?: number
    firmware_version?: string
    installed_at?: string
    [key: string]: any
}

interface SensorReading {
    id: string
    tds: number
    temperature?: number
    recorded_at: string
}

interface MaintenanceLog {
    id: string
    action: string
    performed_by: string
    performed_at: string
    notes?: string
}

interface DeviceDetailModalProps {
    device: ModalDevice | null
    isOpen: boolean
    onClose: () => void
    onRefresh?: () => void
}

type TabType = 'overview' | 'history' | 'maintenance' | 'config'

export default function DeviceDetailModal({ device, isOpen, onClose, onRefresh }: DeviceDetailModalProps) {
    const [activeTab, setActiveTab] = useState<TabType>('overview')
    const [sensorHistory, setSensorHistory] = useState<SensorReading[]>([])
    const [maintenanceLogs, setMaintenanceLogs] = useState<MaintenanceLog[]>([])
    const [loading, setLoading] = useState(false)
    const [updating, setUpdating] = useState(false)
    const [editTdsMin, setEditTdsMin] = useState<number>(device?.safe_tds_min ?? 35)
    const [editTdsMax, setEditTdsMax] = useState<number>(device?.safe_tds_max ?? 175)
    const [isEditingTds, setIsEditingTds] = useState(false)

    useEffect(() => {
        if (device && isOpen) {
            fetchSensorHistory()
            fetchMaintenanceLogs()
        }
    }, [device, isOpen])

    const fetchSensorHistory = async () => {
        if (!device) return
        setLoading(true)
        try {
            const q = query(
                collection(db, 'sensor_data'),
                where('device_id', '==', device.id),
                orderBy('recorded_at', 'desc'),
                limit(50)
            )
            const querySnapshot = await getDocs(q)
            const data = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            })) as SensorReading[]
            setSensorHistory([...data].reverse())
        } catch (err) {
            console.error('Error fetching sensor history:', err)
        }
        setLoading(false)
    }

    const fetchMaintenanceLogs = async () => {
        if (!device) return
        try {
            const q = query(
                collection(db, 'maintenance_logs'),
                where('device_id', '==', device.id),
                orderBy('performed_at', 'desc'),
                limit(20)
            )
            const querySnapshot = await getDocs(q)
            const data = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            })) as MaintenanceLog[]
            setMaintenanceLogs(data)
        } catch (err) {
            console.error('Error fetching maintenance logs:', err)
        }
    }

    const toggleMaintenanceMode = async () => {
        if (!device) return
        setUpdating(true)
        try {
            const newStatus = device.status === 'maintenance' ? 'online' : 'maintenance'
            const deviceRef = doc(db, 'devices', device.id)
            await updateDoc(deviceRef, { status: newStatus })

            // Log the action
            await addDoc(collection(db, 'maintenance_logs'), {
                device_id: device.id,
                action: newStatus === 'maintenance' ? 'Entered Maintenance Mode' : 'Exited Maintenance Mode',
                performed_by: 'Admin',
                performed_at: serverTimestamp(),
                notes: 'Status changed via dashboard'
            })

            onRefresh?.()
        } catch (err) {
            console.error('Error updating device:', err)
        }
        setUpdating(false)
    }

    const handleSaveTdsLimits = async () => {
        if (!device) return

        // Validation
        if (editTdsMin < 0 || editTdsMax < editTdsMin || editTdsMax > 10000) {
            alert('Invalid TDS range. Min must be >= 0 and Max must be >= Min and <= 10000')
            return
        }

        setUpdating(true)
        try {
            const deviceRef = doc(db, 'devices', device.id)
            await updateDoc(deviceRef, {
                safe_tds_min: editTdsMin,
                safe_tds_max: editTdsMax,
                updated_at: serverTimestamp()
            })

            setIsEditingTds(false)
            onRefresh?.()
        } catch (err: any) {
            console.error('Error updating TDS thresholds:', err)
            alert('Failed to update thresholds: ' + (err.message || 'Unknown error'))
        } finally {
            setUpdating(false)
        }
    }

    const getStatusColor = (status: string) => {
        switch (status?.toLowerCase()) {
            case 'online': return 'bg-emerald-500'
            case 'offline': return 'bg-red-500'
            case 'degraded': return 'bg-orange-500'
            case 'maintenance': return 'bg-blue-500'
            default: return 'bg-slate-500'
        }
    }

    const getStatusIcon = (status: string) => {
        switch (status?.toLowerCase()) {
            case 'online': return <CheckCircle className="h-4 w-4" />
            case 'offline': return <AlertTriangle className="h-4 w-4" />
            case 'degraded': return <AlertTriangle className="h-4 w-4" />
            case 'maintenance': return <Wrench className="h-4 w-4" />
            default: return <Activity className="h-4 w-4" />
        }
    }

    if (!isOpen || !device) return null

    return (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center">
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-black/60 backdrop-blur-sm"
                onClick={onClose}
            />

            {/* Modal */}
            <div className="relative w-full sm:max-w-2xl max-h-[90vh] bg-background rounded-t-2xl sm:rounded-2xl border border-border overflow-hidden animate-slide-up">
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-border">
                    <div className="flex items-center gap-3">
                        <div className={`w-3 h-3 rounded-full ${getStatusColor(device.status)}`} />
                        <div>
                            <h2 className="text-lg font-semibold text-foreground">{getDeviceDisplayName(device)}</h2>
                            <p className="text-xs text-muted-foreground">{device.device_id}</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 text-muted-foreground hover:text-foreground hover:bg-accent rounded-lg transition-colors"
                    >
                        <X className="h-5 w-5" />
                    </button>
                </div>

                {/* Tabs */}
                <div className="flex border-b border-border overflow-x-auto">
                    {[
                        { id: 'overview', label: 'Overview', icon: Activity },
                        { id: 'history', label: 'History', icon: History },
                        { id: 'maintenance', label: 'Logs', icon: Wrench },
                        { id: 'config', label: 'Config', icon: Settings },
                    ].map((tab) => {
                        const Icon = tab.icon
                        return (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id as TabType)}
                                className={`flex-1 min-w-[80px] flex items-center justify-center gap-2 py-3 px-4 text-sm font-medium transition-colors ${activeTab === tab.id
                                    ? 'text-primary border-b-2 border-primary bg-primary/5'
                                    : 'text-muted-foreground hover:text-foreground'
                                    }`}
                            >
                                <Icon className="h-4 w-4" />
                                <span className="hidden sm:inline">{tab.label}</span>
                            </button>
                        )
                    })}
                </div>

                {/* Content */}
                <div className="p-4 overflow-y-auto max-h-[60vh]">
                    {/* Overview Tab */}
                    {activeTab === 'overview' && (
                        <div className="space-y-4">
                            {/* Status Cards */}
                            <div className="grid grid-cols-2 gap-3">
                                <div className="bg-accent/10 rounded-xl p-3 border border-border">
                                    <div className="flex items-center gap-2 text-muted-foreground text-xs mb-1">
                                        <Battery className="h-3 w-3" />
                                        Battery
                                    </div>
                                    <p className="text-xl font-bold text-foreground">{device.battery_level ?? '--'}%</p>
                                </div>
                                <div className="bg-accent/10 rounded-xl p-3 border border-border">
                                    <div className="flex items-center gap-2 text-muted-foreground text-xs mb-1">
                                        <Wifi className="h-3 w-3" />
                                        Signal
                                    </div>
                                    <p className="text-xl font-bold text-foreground">{device.signal_strength ?? '--'} dBm</p>
                                </div>
                                <div className="bg-accent/10 rounded-xl p-3 flex flex-col items-center justify-center border border-border">
                                    <div className="flex items-center gap-2 text-muted-foreground text-xs mb-2 w-full">
                                        <Activity className="h-3 w-3" />
                                        Trust Score
                                    </div>
                                    <ConfidenceRing score={device.confidence_score ?? 100} size={50} status={device.status} />
                                </div>
                                <div className="bg-accent/10 rounded-xl p-3 flex flex-col justify-center border border-border">
                                    <div className="flex items-center gap-2 text-muted-foreground text-xs mb-1">
                                        <Activity className="h-3 w-3" />
                                        Health
                                    </div>
                                    <p className="text-sm text-foreground">
                                        {(device.confidence_score ?? 100) > 80 ? 'Excellent' : (device.confidence_score ?? 100) > 50 ? 'Fair' : 'Poor'}
                                    </p>
                                </div>
                            </div>

                            {/* Health Timeline */}
                            <HealthTimeline deviceId={device.id} />

                            {/* Location */}
                            <div className="bg-accent/10 rounded-xl p-3 border border-border">
                                <div className="flex items-center gap-2 text-muted-foreground text-xs mb-1">
                                    <MapPin className="h-3 w-3" />
                                    Location
                                </div>
                                <p className="text-sm text-foreground">{device.location_name || 'Not set'}</p>
                                {device.latitude && device.longitude && (
                                    <p className="text-xs text-muted-foreground mt-1">
                                        {device.latitude.toFixed(4)}, {device.longitude.toFixed(4)}
                                    </p>
                                )}
                            </div>

                            {/* Status & Actions */}
                            <div className="bg-accent/10 rounded-xl p-3 border border-border">
                                <div className="flex items-center justify-between">
                                    <div>
                                        <div className="flex items-center gap-2 text-muted-foreground text-xs mb-1">
                                            <Clock className="h-3 w-3" />
                                            Status
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className={`px-2 py-1 rounded-full text-xs font-medium flex items-center gap-1 ${getStatusColor(device.status)} text-white`}>
                                                {getStatusIcon(device.status)}
                                                {device.status?.toUpperCase()}
                                            </span>
                                        </div>
                                    </div>
                                    <button
                                        onClick={toggleMaintenanceMode}
                                        disabled={updating}
                                        className="px-3 py-2 bg-primary/10 hover:bg-primary/20 text-primary text-sm rounded-lg transition-colors flex items-center gap-2"
                                    >
                                        <Wrench className="h-4 w-4" />
                                        {device.status === 'maintenance' ? 'Exit' : 'Enter'} Maintenance
                                    </button>
                                </div>
                            </div>

                            {/* Last Seen */}
                            {(device.last_seen_at || device.last_seen) && (
                                <div className="text-center text-xs text-muted-foreground">
                                    Last seen: {new Date(device.last_seen_at || device.last_seen!).toLocaleString()}
                                </div>
                            )}
                        </div>
                    )}

                    {/* History Tab */}
                    {activeTab === 'history' && (
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <h3 className="text-sm font-medium text-slate-300">TDS Readings (Last 50)</h3>
                                <button
                                    onClick={fetchSensorHistory}
                                    className="p-2 text-slate-400 hover:text-white rounded-lg"
                                >
                                    <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                                </button>
                            </div>

                            {sensorHistory.length > 0 ? (
                                <div className="h-[250px] w-full">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <LineChart data={sensorHistory}>
                                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                                            <XAxis
                                                dataKey="recorded_at"
                                                tick={{ fill: '#64748b', fontSize: 10 }}
                                                tickFormatter={(time) => new Date(time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                            />
                                            <YAxis tick={{ fill: '#64748b', fontSize: 10 }} />
                                            <Tooltip
                                                contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                                                labelFormatter={(label) => new Date(label).toLocaleString()}
                                            />
                                            <Line
                                                type="monotone"
                                                dataKey="tds"
                                                stroke="#06b6d4"
                                                strokeWidth={2}
                                                dot={false}
                                            />
                                        </LineChart>
                                    </ResponsiveContainer>
                                </div>
                            ) : (
                                <div className="text-center py-8 text-slate-500">
                                    No sensor data available
                                </div>
                            )}
                        </div>
                    )}

                    {/* Maintenance Logs Tab */}
                    {activeTab === 'maintenance' && (
                        <div className="space-y-3">
                            <h3 className="text-sm font-medium text-slate-300">Maintenance History</h3>
                            {maintenanceLogs.length > 0 ? (
                                maintenanceLogs.map((log) => (
                                    <div key={log.id} className="bg-slate-800/50 rounded-xl p-3">
                                        <div className="flex items-start justify-between">
                                            <div>
                                                <p className="text-sm font-medium text-white">{log.action}</p>
                                                <p className="text-xs text-slate-400 mt-1">By: {log.performed_by}</p>
                                                {log.notes && (
                                                    <p className="text-xs text-slate-500 mt-1">{log.notes}</p>
                                                )}
                                            </div>
                                            <p className="text-xs text-slate-500">
                                                {new Date(log.performed_at).toLocaleDateString()}
                                            </p>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="text-center py-8 text-slate-500">
                                    No maintenance logs
                                </div>
                            )}
                        </div>
                    )}

                    {/* Config Tab */}
                    {activeTab === 'config' && (
                        <div className="space-y-3">
                            <h3 className="text-sm font-medium text-slate-300">Device Configuration</h3>

                            <div className="bg-slate-800/50 rounded-xl divide-y divide-slate-700">
                                <div className="flex items-center justify-between p-3">
                                    <span className="text-sm text-slate-400">Device ID</span>
                                    <span className="text-sm text-white font-mono">{device.node_number || device.device_id || device.id.split('-')[0]}</span>
                                </div>
                                <div className="flex items-center justify-between p-3">
                                    <span className="text-sm text-slate-400">Firmware</span>
                                    <span className="text-sm text-white">{device.metadata?.firmware_version || device.firmware_version || 'v1.0.0'}</span>
                                </div>
                                <div className="flex items-center justify-between p-3">
                                    <span className="text-sm text-slate-400">Installed</span>
                                    <span className="text-sm text-white">
                                        {new Date(device.deployment_date || device.installed_at || device.created_at).toLocaleDateString()}
                                    </span>
                                </div>
                            </div>

                            {/* TDS Threshold Configuration Section */}
                            <div className="bg-slate-800/50 rounded-xl overflow-hidden">
                                <div className="p-4 space-y-3 border-b border-slate-700">
                                    <div className="flex items-center justify-between">
                                        <h4 className="text-sm font-medium text-slate-300">Water Quality Thresholds (PPM)</h4>
                                        {!isEditingTds && (
                                            <button
                                                onClick={() => {
                                                    setEditTdsMin(device.safe_tds_min ?? 35)
                                                    setEditTdsMax(device.safe_tds_max ?? 175)
                                                    setIsEditingTds(true)
                                                }}
                                                className="text-xs px-2 py-1 bg-primary/10 hover:bg-primary/20 text-primary rounded transition-colors"
                                            >
                                                Edit
                                            </button>
                                        )}
                                    </div>

                                    {isEditingTds ? (
                                        <div className="space-y-3">
                                            <div className="grid grid-cols-2 gap-3">
                                                <div>
                                                    <label className="text-xs text-slate-400 block mb-2">Safe Minimum</label>
                                                    <input
                                                        type="number"
                                                        value={editTdsMin}
                                                        onChange={(e) => setEditTdsMin(Number(e.target.value))}
                                                        disabled={updating}
                                                        className="w-full px-3 py-2 bg-slate-700 border border-slate-600 rounded-lg text-white text-sm focus:outline-none focus:border-primary disabled:opacity-50"
                                                        placeholder="e.g., 35"
                                                    />
                                                </div>

                                                <div>
                                                    <label className="text-xs text-slate-400 block mb-2">Safe Maximum</label>
                                                    <input
                                                        type="number"
                                                        value={editTdsMax}
                                                        onChange={(e) => setEditTdsMax(Number(e.target.value))}
                                                        disabled={updating}
                                                        className="w-full px-3 py-2 bg-slate-700 border border-slate-600 rounded-lg text-white text-sm focus:outline-none focus:border-primary disabled:opacity-50"
                                                        placeholder="e.g., 175"
                                                    />
                                                </div>
                                            </div>

                                            <p className="text-xs text-slate-500">
                                                ℹ️ Readings outside this range will trigger alerts
                                            </p>

                                            <div className="flex gap-2">
                                                <button
                                                    onClick={handleSaveTdsLimits}
                                                    disabled={updating}
                                                    className="flex-1 px-3 py-2 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 text-sm rounded-lg transition-colors disabled:opacity-50"
                                                >
                                                    {updating ? 'Saving...' : 'Save'}
                                                </button>
                                                <button
                                                    onClick={() => setIsEditingTds(false)}
                                                    disabled={updating}
                                                    className="flex-1 px-3 py-2 bg-slate-700 hover:bg-slate-600 text-slate-300 text-sm rounded-lg transition-colors"
                                                >
                                                    Cancel
                                                </button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-2 gap-3">
                                            <div className="bg-slate-700/50 rounded p-2">
                                                <p className="text-xs text-slate-500">Minimum</p>
                                                <p className="text-lg font-bold text-white">{device.safe_tds_min ?? 35}</p>
                                            </div>
                                            <div className="bg-slate-700/50 rounded p-2">
                                                <p className="text-xs text-slate-500">Maximum</p>
                                                <p className="text-lg font-bold text-white">{device.safe_tds_max ?? 175}</p>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <button className="w-full flex items-center justify-between p-3 bg-slate-800/50 rounded-xl hover:bg-slate-800 transition-colors">
                                <span className="text-sm text-white">Update Firmware</span>
                                <ChevronRight className="h-4 w-4 text-slate-400" />
                            </button>

                            <button className="w-full flex items-center justify-between p-3 bg-red-500/10 rounded-xl hover:bg-red-500/20 transition-colors border border-red-500/20">
                                <span className="text-sm text-red-400">Reset Device</span>
                                <ChevronRight className="h-4 w-4 text-red-400" />
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}

import { useState, useEffect, useMemo } from 'react'
import { getDeviceDisplayName } from '../lib/constants'
import { toast } from 'sonner'
import {
    X, MapPin, Activity, Settings, History, CheckCircle, Wrench, RefreshCw, Minimize2
} from 'lucide-react'
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts'
import HealthTimeline from './HealthTimeline'
import ConfidenceRing from './ConfidenceRing'
import { useUI } from '../context/UIContext'
import { useDevice, useUpdateDevice } from '../hooks/useDeviceQueries'
import { useDeviceThingSpeakChartData } from '../hooks/useThingSpeakQueries'
import { useRole } from '../context/RoleContext'
import type { Device } from '../types'
import { cn } from '@/lib/utils'

type TabType = 'overview' | 'history' | 'maintenance' | 'config'

export default function DeviceInspector() {
    const { inspectorDeviceId, closeInspector, isMobile } = useUI()
    const { hasPermission, isAtLeast } = useRole()
    
    // Hooks for data fetching
    const { data: device, isLoading: deviceLoading } = useDevice(inspectorDeviceId || undefined)
    const { data: sensorData = [], isLoading: sensorLoading } = useDeviceThingSpeakChartData(device || undefined, 100)
    const updateMutation = useUpdateDevice()

    const [activeTab, setActiveTab] = useState<TabType>('overview')
    const [renderNow] = useState(() => Date.now())
    const [updating, setUpdating] = useState(false)
    const [isEditing, setIsEditing] = useState(false)
    const [editForm, setEditForm] = useState({ name: '', location_name: '', firmware_version: '' })
    const [prevDeviceId, setPrevDeviceId] = useState<string | null>(null)

    if (device && device.id !== prevDeviceId) {
        setPrevDeviceId(device.id)
        setEditForm({
            name: device.name,
            location_name: device.location_name || '',
            firmware_version: device.metadata?.firmware_version?.toString() || ''
        })
    }

    // Map sensor data to SensorReading format
    const sensorHistory = useMemo(() => {
        return sensorData.map((d, i) => ({
            id: i.toString(),
            tds: d.tds,
            temperature: d.temperature,
            recorded_at: d.timestamp
        }))
    }, [sensorData])

    const latestReading = useMemo(() => {
        return sensorHistory.length > 0 ? sensorHistory[sensorHistory.length - 1] : null
    }, [sensorHistory])

    // Removed sync useEffect to avoid cascading renders lint error

    const handleSaveConfig = async () => {
        if (!device) return
        setUpdating(true)
        const toastId = toast.loading('Saving configuration...')
        try {
            const updatedMetadata = { 
                ...device.metadata, 
                firmware_version: editForm.firmware_version 
            }
            
            await updateMutation.mutateAsync({
                id: device.id,
                updates: {
                    name: editForm.name,
                    location_name: editForm.location_name,
                    metadata: updatedMetadata
                }
            })

            setIsEditing(false)
            toast.success('Configuration saved successfully', { id: toastId })
        } catch (err) {
            console.error('Failed to save config', err)
            toast.error('Failed to save configuration', { id: toastId })
        }
        setUpdating(false)
    }

    const handleRegenerateQR = async () => {
        if (!device) return
        const confirmed = window.confirm('Are you sure you want to regenerate the QR code? The old QR code will stop working immediately.')
        if (!confirmed) return

        setUpdating(true)
        const toastId = toast.loading('Regenerating QR code...')

        try {
            await updateMutation.mutateAsync({
                id: device.id,
                updates: {
                    qr_rotation_pending: true,
                    updated_at: new Date().toISOString()
                }
            })
            
            toast.success('QR Code rotation requested!', { id: toastId })
        } catch (err) {
            console.error('Failed to rotate QR', err)
            toast.error('Failed to rotate QR code', { id: toastId })
        }
        setUpdating(false)
    }

    const toggleMaintenanceMode = async () => {
        if (!device) return
        setUpdating(true)
        const toastId = toast.loading('Updating status...')
        try {
            const newStatus = device.status === 'maintenance' ? 'online' : 'maintenance'
            await updateMutation.mutateAsync({
                id: device.id,
                updates: { status: newStatus as Device['status'] }
            })
            toast.success(`Device ${newStatus === 'maintenance' ? 'entered maintenance mode' : 'is now online'}`, { id: toastId })
        } catch (err) {
            console.error(err)
            toast.error('Failed to update status', { id: toastId })
        }
        setUpdating(false)
    }

    const getStatusColor = (status: string) => {
        switch (status?.toLowerCase()) {
            case 'online': return 'bg-emerald-500'
            case 'offline': return 'bg-red-500'
            case 'degraded': return 'bg-orange-500'
            case 'maintenance': return 'bg-blue-500'
            default: return 'bg-slate-500'
        }
    }

    return (
        <div className={cn(
            "fixed top-0 right-0 h-full bg-background/95 backdrop-blur-2xl border-l border-border shadow-2xl z-50 transition-all duration-500 ease-in-out flex flex-col",
            isMobile ? "w-full" : "w-[400px]",
            inspectorDeviceId ? "translate-x-0" : "translate-x-full"
        )}>
            {/* Mobile Backdrop */}
            {inspectorDeviceId && isMobile && (
                <div 
                    className="fixed inset-0 bg-black/40 -z-10 md:hidden animate-in fade-in duration-300" 
                    onClick={closeInspector} 
                />
            )}

            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-border bg-accent/5">
                <div className="flex items-center gap-3">
                    {device && <div className={`w-3 h-3 rounded-full ${getStatusColor(device.status)} shadow-[0_0_8px_currentColor]`} />}
                    <div>
                        <h2 className="text-sm font-black text-foreground tracking-wide uppercase">{device ? getDeviceDisplayName(device) : 'Loading...'}</h2>
                        <p className="text-[10px] text-muted-foreground font-mono">{device?.id?.slice(0, 8)}...</p>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={closeInspector} className="p-2 hover:bg-accent/10 rounded-lg text-muted-foreground hover:text-foreground transition-colors">
                        <Minimize2 className="h-4 w-4" />
                    </button>
                    <button onClick={closeInspector} className="p-2 hover:bg-red-500/20 rounded-lg text-muted-foreground hover:text-red-400 transition-colors">
                        <X className="h-4 w-4" />
                    </button>
                </div>
            </div>

            {deviceLoading && !device ? (
                <div className="flex-1 flex items-center justify-center text-slate-500">
                    <RefreshCw className="h-6 w-6 animate-spin" />
                </div>
            ) : device ? (
                <>
                    {/* Tabs */}
                    <div className="flex border-b border-border">
                        {[
                            { id: 'overview', icon: Activity },
                            { id: 'history', icon: History },
                            { id: 'config', icon: Settings },
                        ].map((tab) => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id as TabType)}
                                className={`flex-1 py-3 flex justify-center transition-colors ${activeTab === tab.id ? 'text-primary border-b-2 border-primary bg-primary/5' : 'text-muted-foreground hover:text-foreground'}`}
                            >
                                <tab.icon className="h-4 w-4" />
                            </button>
                        ))}
                    </div>

                    {/* Scrollable Content */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-hide">
                        {/* Overview */}
                        {activeTab === 'overview' && (
                            <div className="space-y-4">
                                <div className="grid grid-cols-2 gap-3">
                                    <div className="bg-accent/5 rounded-xl p-3 border border-border">
                                        <p className="text-xs text-muted-foreground mb-1 font-bold">Confidence</p>
                                        <div className="flex justify-center py-2">
                                            <ConfidenceRing score={device.confidence_score ?? 100} size={60} status={device.status} />
                                        </div>
                                    </div>
                                    <div className="bg-accent/5 rounded-xl p-3 border border-border space-y-3">
                                        <div>
                                            <p className="text-xs text-muted-foreground font-bold">Last Reading</p>
                                            {device.last_reading_at ? (
                                                <p className={`text-sm font-mono ${new Date(device.last_reading_at).getTime() < renderNow - 15 * 60 * 1000 ? 'text-orange-400' : 'text-emerald-400'}`}>
                                                    {new Date(device.last_reading_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </p>
                                            ) : (
                                                <p className="text-sm font-mono text-muted-foreground">No Data</p>
                                            )}
                                        </div>
                                        <div>
                                            <p className="text-xs text-muted-foreground font-bold">Heatbeat</p>
                                            <p className="text-sm font-mono text-emerald-400">
                                                {device.last_seen_at ? new Date(device.last_seen_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '-'}
                                            </p>
                                        </div>
                                    </div>
                                </div>

                                <HealthTimeline deviceId={device.id} />

                                <div className="bg-accent/5 rounded-xl p-4 border border-border">
                                    <div className="flex items-center gap-2 mb-3">
                                        <MapPin className="h-4 w-4 text-blue-400" />
                                        <span className="text-sm font-medium text-foreground">Location</span>
                                    </div>
                                    <p className="text-sm text-muted-foreground">{device.location_name || 'Unknown Location'}</p>
                                    <p className="text-xs text-muted-foreground/60 mt-1 font-mono">{device.latitude?.toFixed(4)}, {device.longitude?.toFixed(4)}</p>
                                </div>

                                {hasPermission('maintenance_mode') && (
                                    <button
                                        onClick={toggleMaintenanceMode}
                                        disabled={updating}
                                        className={`w-full py-3 rounded-xl border flex items-center justify-center gap-2 transition-all ${device.status === 'maintenance'
                                            ? 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20'
                                            : 'border-amber-500/30 bg-amber-500/10 text-amber-400 hover:bg-amber-500/20'}`}
                                    >
                                        <Wrench className="h-4 w-4" />
                                        {device.status === 'maintenance' ? 'Exit Maintenance' : 'Enter Maintenance Mode'}
                                    </button>
                                )}
                            </div>
                        )}

                        {/* History */}
                        {activeTab === 'history' && (
                            <div className="space-y-4">
                                <div className="h-64 w-full bg-white/5 rounded-xl p-2 border border-white/5">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <LineChart data={sensorHistory}>
                                            <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                                            <XAxis dataKey="recorded_at" hide />
                                            <YAxis stroke="#666" fontSize={10} />
                                            <Tooltip contentStyle={{ backgroundColor: '#000', border: '1px solid #333' }} />
                                            <Line type="monotone" dataKey="tds" stroke="#3b82f6" dot={false} strokeWidth={2} />
                                        </LineChart>
                                    </ResponsiveContainer>
                                </div>
                                <div className="space-y-2">
                                    {sensorHistory.map((reading, i) => (
                                        <div key={i} className="flex justify-between text-xs py-2 border-b border-white/5">
                                            <span className="text-slate-400">{new Date(reading.recorded_at).toLocaleTimeString()}</span>
                                            <span className="text-white font-mono">{reading.tds.toFixed(1)} PPM</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Config */}
                        {activeTab === 'config' && (
                            <div className="space-y-4">
                                <div className="p-4 bg-white/5 rounded-xl border border-white/5 relative">
                                    <div className="flex justify-between items-center mb-4">
                                        <h3 className="text-xs font-bold text-slate-500 uppercase">Device Metadata</h3>
                                        {isAtLeast('admin') && (
                                            <button
                                                onClick={() => {
                                                    if (isEditing) handleSaveConfig()
                                                    else setIsEditing(true)
                                                }}
                                                className={`p-1.5 rounded-lg transition-colors ${isEditing ? 'bg-emerald-500/20 text-emerald-400' : 'bg-white/5 text-slate-400 hover:text-white'}`}
                                            >
                                                {isEditing ? <CheckCircle className="w-4 h-4" /> : <Wrench className="w-4 h-4" />}
                                            </button>
                                        )}
                                    </div>

                                    <div className="space-y-4 text-sm">
                                        <div className="space-y-1">
                                            <span className="text-slate-400 text-xs">Device Name</span>
                                            {isEditing ? (
                                                <input
                                                    className="w-full bg-black/50 border border-white/10 rounded px-2 py-1 text-white focus:outline-none focus:border-blue-500"
                                                    value={editForm.name}
                                                    onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                                                />
                                            ) : (
                                                <div className="text-white font-medium">{device.name}</div>
                                            )}
                                        </div>

                                        <div className="space-y-1">
                                            <span className="text-muted-foreground text-xs font-bold uppercase tracking-wider">Location Name</span>
                                            {isEditing ? (
                                                <input
                                                    className="w-full bg-background border border-border rounded px-2 py-1 text-foreground focus:outline-none focus:border-primary"
                                                    value={editForm.location_name}
                                                    onChange={e => setEditForm({ ...editForm, location_name: e.target.value })}
                                                />
                                            ) : (
                                                <div className="text-foreground font-medium">{device.location_name || '-'}</div>
                                            )}
                                        </div>

                                        <div className="space-y-1">
                                            <span className="text-muted-foreground text-xs font-bold uppercase tracking-wider">Firmware Version</span>
                                            {isEditing ? (
                                                <input
                                                    className="w-full bg-background border border-border rounded px-2 py-1 text-foreground focus:outline-none focus:border-primary"
                                                    value={editForm.firmware_version}
                                                    onChange={e => setEditForm({ ...editForm, firmware_version: e.target.value })}
                                                />
                                            ) : (
                                                <div className="text-foreground font-mono">{device.metadata?.firmware_version || 'v1.0.0'}</div>
                                            )}
                                        </div>

                                        <div className="bg-accent/5 rounded-xl p-4 border border-border">
                                            <div className="flex items-center justify-between mb-4">
                                                <h3 className="text-xs font-black text-muted-foreground uppercase tracking-widest">Live Metrics</h3>
                                                <div className={`animate-pulse flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border transition-colors ${sensorLoading ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'}`}>
                                                    <span className={`w-1 h-1 rounded-full ${sensorLoading ? 'bg-amber-500 animate-ping' : 'bg-emerald-500'}`} />
                                                    {sensorLoading ? 'Syncing...' : 'Live'}
                                                </div>
                                            </div>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div className="space-y-1">
                                                    <span className="text-[10px] font-black text-muted-foreground uppercase tracking-tighter">Current TDS</span>
                                                    <div className="text-2xl font-black font-mono text-foreground">{latestReading?.tds || '--'}</div>
                                                </div>
                                                <div className="space-y-1">
                                                    <span className="text-[10px] font-black text-muted-foreground uppercase tracking-tighter">Water Temp</span>
                                                    <div className="text-2xl font-black font-mono text-foreground">{latestReading?.temperature ? `${latestReading.temperature.toFixed(1)}°` : '--'}</div>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-2 gap-4 pt-2">
                                            <div>
                                                <span className="text-muted-foreground text-xs block mb-1 font-bold uppercase">Installed</span>
                                                <div className="text-foreground font-medium">{new Date(device.deployment_date || device.created_at || renderNow).toLocaleDateString()}</div>
                                            </div>
                                            <div>
                                                <span className="text-muted-foreground text-xs block mb-1 font-bold uppercase">Maintenance</span>
                                                <div className="text-foreground font-medium">{device.metadata?.last_maintenance ? new Date(device.metadata.last_maintenance).toLocaleDateString() : '-'}</div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {isAtLeast('admin') && (
                                    <div className="mt-4 pt-4 border-t border-border">
                                        <h4 className="text-xs font-bold text-red-500 uppercase mb-2">Security Zone</h4>
                                        <button
                                            onClick={handleRegenerateQR}
                                            disabled={updating}
                                            className="w-full py-2 bg-red-500/10 hover:bg-red-500/20 text-red-500 rounded-lg text-xs font-bold transition-colors border border-red-500/20 shadow-sm"
                                        >
                                            {updating ? 'Rotating...' : 'Regenerate QR Code'}
                                        </button>
                                        <p className="text-[10px] text-muted-foreground mt-2 text-center font-medium">
                                            Warning: This will immediately invalidate the physical QR code.
                                        </p>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </>
            ) : null}
        </div>
    )
}

import { useState } from 'react'
import { Check, ChevronDown, ChevronUp } from 'lucide-react'
import { type Device } from '../types'
import ConfidenceRing from './ConfidenceRing'

interface DeviceTableProps {
    devices: Device[]
    loading?: boolean
    onDeviceClick?: (device: Device) => void
}

type SortKey = keyof Device | 'tds' | 'temperature'
type SortDirection = 'asc' | 'desc'

export default function DeviceTable({ devices, loading, onDeviceClick }: DeviceTableProps) {
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
    const [sortKey, setSortKey] = useState<SortKey>('name')
    const [sortDirection, setSortDirection] = useState<SortDirection>('asc')
    const [renderNow] = useState(() => Date.now())

    // Handle Selection
    const toggleSelection = (id: string, e: React.MouseEvent) => {
        e.stopPropagation()
        const newSelected = new Set(selectedIds)
        if (newSelected.has(id)) {
            newSelected.delete(id)
        } else {
            newSelected.add(id)
        }
        setSelectedIds(newSelected)
    }

    const toggleAll = () => {
        if (selectedIds.size === devices.length) {
            setSelectedIds(new Set())
        } else {
            setSelectedIds(new Set(devices.map(d => d.id)))
        }
    }

    // Handle Sorting
    const handleSort = (key: SortKey) => {
        if (sortKey === key) {
            setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')
        } else {
            setSortKey(key)
            setSortDirection('asc')
        }
    }

    // Sort Logic
    const sortedDevices = [...devices].sort((a, b) => {
        const valA = a[sortKey as keyof Device]
        const valB = b[sortKey as keyof Device]

        // Mock data handling for TDS/Temp since they aren't on Device object strictly in our current mock flow (they are in sensorData)
        // For now we will sort by the fields present on Device

        if (valA === valB) return 0

        const comparison = valA! > valB! ? 1 : -1
        return sortDirection === 'asc' ? comparison : -comparison
    })

    if (loading) return <div className="p-8 text-center text-slate-500">Loading devices...</div>

    return (
        <div className="glass-card rounded-xl overflow-hidden flex flex-col h-full">
            {/* Table Header */}
            <div className="p-6 border-b border-white/5 flex items-center justify-between">
                <div>
                    <h3 className="text-lg font-semibold text-white tracking-tight">Registered Devices</h3>
                    <p className="text-xs text-[#86868b]">{devices.length} nodes active</p>
                </div>
                {selectedIds.size > 0 && (
                    <div className="flex items-center gap-2 animate-fade-in">
                        <span className="text-xs text-[#86868b] font-medium">{selectedIds.size} selected</span>
                        <button className="text-red-400 text-xs hover:text-red-300 font-medium transition-colors px-2 py-1 rounded-md hover:bg-white/5">
                            Delete
                        </button>
                    </div>
                )}
            </div>

            <div className="overflow-x-auto flex-1 custom-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead className="sticky top-0 bg-white/5 backdrop-blur-2xl z-20">
                        <tr className="text-xs text-[#6e6e73] font-medium border-b border-white/5 uppercase tracking-wider">
                            <th className="p-4 pl-6 w-12">
                                <button
                                    onClick={toggleAll}
                                    className={`w-5 h-5 rounded-full border flex items-center justify-center transition-all ${selectedIds.size === devices.length && devices.length > 0
                                        ? 'bg-blue-500 border-blue-500 text-white'
                                        : 'border-[#6e6e73] hover:border-white'
                                        }`}
                                >
                                    {selectedIds.size === devices.length && devices.length > 0 && <Check className="w-3 h-3" strokeWidth={3} />}
                                </button>
                            </th>
                            <th onClick={() => handleSort('name')} className="p-4 cursor-pointer hover:text-foreground transition-colors group">
                                <div className="flex items-center gap-1">
                                    Device Name
                                    {sortKey === 'name' && (sortDirection === 'asc' ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />)}
                                </div>
                            </th>
                            <th onClick={() => handleSort('location_name')} className="p-4 cursor-pointer hover:text-foreground transition-colors">
                                Location Name
                            </th>
                            <th className="p-4 text-right">TDS (ppm)</th>
                            <th className="p-4 text-right">Temp (°C)</th>
                            <th className="p-4 text-center">Confidence</th>
                            <th className="p-4 text-center">Status</th>
                            <th className="p-4 text-right pr-6">Last Seen</th>
                        </tr>
                    </thead>
                    <tbody className="text-sm text-muted-foreground">
                        {sortedDevices.map((device) => {
                            const isSelected = selectedIds.has(device.id)
                            return (
                                <tr
                                    key={device.id}
                                    onClick={() => onDeviceClick?.(device)}
                                    className={`
                                        border-b border-border transition-all cursor-pointer group relative
                                        ${isSelected ? 'bg-primary/10' : 'hover:bg-accent/50'}
                                    `}
                                >
                                    <td className="p-4 pl-6 relative z-10" onClick={(e) => e.stopPropagation()}>
                                        <button
                                            onClick={(e) => toggleSelection(device.id, e)}
                                            className={`w-5 h-5 rounded-full border flex items-center justify-center transition-all ${isSelected
                                                ? 'bg-primary border-primary text-primary-foreground'
                                                : 'border-muted-foreground group-hover:border-foreground'
                                                }`}
                                        >
                                            {isSelected && <Check className="w-3 h-3" strokeWidth={3} />}
                                        </button>
                                    </td>
                                    <td className="p-4 font-medium text-foreground group-hover:text-primary transition-colors">
                                        {device.location_name || device.name}
                                    </td>
                                    <td className="p-4 text-muted-foreground">{device.location_name}</td>
                                    <td className="p-4 text-right font-mono text-foreground">
                                        {/* Real TDS from device props */}
                                        {(device as any).latest_tds?.toFixed(0) || '--'}
                                    </td>
                                    <td className="p-4 text-right font-mono text-muted-foreground">
                                        {(device as any).latest_temp?.toFixed(1) || '--'}
                                    </td>
                                    <td className="p-4 flex justify-center">
                                        <div onClick={(e) => e.stopPropagation()}>
                                            <ConfidenceRing score={device.confidence_score ?? 100} size={32} status={device.status} />
                                        </div>
                                    </td>
                                    <td className="p-4 flex justify-center">
                                        <div onClick={(e) => e.stopPropagation()}>
                                            <ConfidenceRing score={device.confidence_score ?? 100} size={32} status={device.status} />
                                        </div>
                                    </td>
                                    <td className="p-4 text-center">
                                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[10px] font-medium border border-border ${device.status === 'online' ? 'bg-green-500/10 text-green-600 dark:text-green-400' :
                                                device.status === 'critical' ? 'bg-red-500/10 text-red-600 dark:text-red-400' : 'bg-slate-500/10 text-slate-600 dark:text-slate-400'
                                            }`}>
                                            <span className={`w-1 h-1 rounded-full ${device.status === 'online' ? 'bg-green-500' :
                                                    device.status === 'critical' ? 'bg-red-500' : 'bg-slate-500'
                                                }`} />
                                            {device.status.charAt(0).toUpperCase() + device.status.slice(1)}
                                        </span>
                                    </td>
                                    <td className="p-4 text-right pr-6 text-muted-foreground text-xs font-mono">
                                        {new Date(device.last_seen_at || renderNow).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </td>
                                </tr>
                            )
                        })}
                    </tbody>
                </table>
            </div>
        </div >
    )
}

import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts'

interface DualPieChartProps {
    connectivityData: Array<{ name: string; value: number; fill: string }>
    tdsData: Array<{ name: string; value: number; fill: string }>
}

/**
 * Dual Pie Chart Component
 * 
 * Features:
 * - Inner ring: Online/Offline connectivity status
 * - Outer ring: Safe/Critical TDS categorization
 * - Custom tooltips with device counts
 * - Percentage labels
 * - Responsive sizing
 */
// Custom tooltip (moved outside to prevent unmounts on re-render)
const CustomTooltip = ({ active, payload, connectivityData, tdsData }: any) => {
    if (active && payload && payload.length) {
        const data = payload[0]
        const total = connectivityData.reduce((sum: any, item: any) => sum + item.value, 0) +
            tdsData.reduce((sum: any, item: any) => sum + item.value, 0)
        const percentage = ((data.value / total) * 100).toFixed(1)

        return (
            <div className="px-3 py-2 rounded-lg border border-white/10 shadow-xl backdrop-blur-xl bg-black/90">
                <div className="flex items-center gap-2">
                    <div
                        className="w-2.5 h-2.5 rounded-full"
                        style={{ backgroundColor: data.payload.fill }}
                    />
                    <span className="text-white text-sm font-medium">{data.name}</span>
                </div>
                <p className="text-white/80 text-xs mt-1">
                    {data.value} devices ({percentage}%)
                </p>
            </div>
        )
    }
    return null
}

export function DualPieChart({ connectivityData, tdsData }: DualPieChartProps) {

    // Custom label for percentages
    const renderLabel = (entry: any) => {
        // Determine which dataset this entry belongs to (Connectivity or TDS)
        const isConnectivity = connectivityData.some(d => d.name === entry.name)
        const currentData = isConnectivity ? connectivityData : tdsData

        const total = currentData.reduce((sum, item) => sum + item.value, 0)
        if (total === 0) return ''

        const percentage = Math.round((entry.value / total) * 100)
        return percentage > 5 ? `${percentage}%` : '' // Only show if > 5%
    }

    return (
        <div className="relative h-full">
            <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                    {/* Inner Ring - Connectivity Status */}
                    <Pie
                        data={connectivityData}
                        dataKey="value"
                        cx="50%"
                        cy="50%"
                        innerRadius={50}
                        outerRadius={70}
                        paddingAngle={2}
                        strokeWidth={0}
                        label={renderLabel}
                        labelLine={false}
                    >
                        {connectivityData.map((entry, index) => (
                            <Cell key={`connectivity-${index}`} fill={entry.fill} />
                        ))}
                    </Pie>

                    {/* Outer Ring - TDS Category */}
                    <Pie
                        data={tdsData}
                        dataKey="value"
                        cx="50%"
                        cy="50%"
                        innerRadius={80}
                        outerRadius={100}
                        paddingAngle={2}
                        strokeWidth={0}
                        label={renderLabel}
                        labelLine={false}
                    >
                        {tdsData.map((entry, index) => (
                            <Cell key={`tds-${index}`} fill={entry.fill} />
                        ))}
                    </Pie>

                    <Tooltip content={<CustomTooltip connectivityData={connectivityData} tdsData={tdsData} />} />
                </PieChart>
            </ResponsiveContainer>

            {/* Legend */}
            <div className="absolute bottom-0 left-0 right-0 flex flex-col gap-2 text-xs">
                {/* Inner Ring Legend */}
                <div className="flex items-center justify-center gap-3">
                    <span className="text-white/40 text-[10px]">Inner:</span>
                    {connectivityData.map((item, index) => (
                        <div key={`legend-conn-${index}`} className="flex items-center gap-1.5">
                            <div
                                className="w-2 h-2 rounded-full"
                                style={{ backgroundColor: item.fill }}
                            />
                            <span className="text-white/60 text-[10px]">{item.name}</span>
                        </div>
                    ))}
                </div>

                {/* Outer Ring Legend */}
                <div className="flex items-center justify-center gap-3">
                    <span className="text-white/40 text-[10px]">Outer:</span>
                    {tdsData.map((item, index) => (
                        <div key={`legend-tds-${index}`} className="flex items-center gap-1.5">
                            <div
                                className="w-2 h-2 rounded-full"
                                style={{ backgroundColor: item.fill }}
                            />
                            <span className="text-white/60 text-[10px]">{item.name}</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}

import ReactECharts from 'echarts-for-react'
import type { EChartsOption } from 'echarts'
import { useTheme } from '../context/ThemeContext'

interface PieChartData {
    name: string
    value: number
    color: string
}

interface EChartsNestedPieChartProps {
    connectivityData: PieChartData[]
    tdsData: PieChartData[]
}

/**
 * Enhanced Nested/Concentric Donut Chart
 * - Inner ring: TDS Status
 * - Outer ring: Connectivity Status
 * - No percentages in labels
 * - Shows device count on hover
 * - Beautiful animations and colors
 */
export function EChartsNestedPieChart({ connectivityData, tdsData }: EChartsNestedPieChartProps) {
    const { resolvedTheme } = useTheme()
    const isDark = resolvedTheme === 'dark'

    // High-Saturation Neon Color Palette
    const colorPalette = {
        online: '#818cf8',
        offline: isDark ? '#475569' : '#94a3b8',
        safeTDS: '#00df81',
        criticalTDS: '#ff0055',
    }

    const option: EChartsOption = {
        backgroundColor: 'transparent',
        tooltip: {
            trigger: 'item',
            formatter: (params: any) => {
                const { name, value, percent } = params
                const bgColor = isDark ? 'rgba(0,0,0,0.85)' : 'rgba(255,255,255,0.7)'
                const textColor = isDark ? '#fff' : '#0f172a'
                const mutedColor = isDark ? '#94a3b8' : '#64748b'
                const borderColor = isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.08)'

                return `<div style="padding: 10px 16px; border-radius: 12px; background: ${bgColor}; backdrop-filter: blur(16px); border: 1px solid ${borderColor}; box-shadow: 0 10px 30px rgba(0,0,0,0.1);">
                    <div style="font-weight: 700; color: ${textColor}; margin-bottom: 4px; display: flex; align-items: center; gap: 8px;">
                        <span style="width: 8px; height: 8px; border-radius: 50%; background: ${params.color};"></span>
                        ${name}
                    </div>
                    <div style="font-size: 13px; color: ${mutedColor};">
                        Devices: <strong style="color: ${textColor};">${value}</strong>
                        <span style="margin-left: 8px;">(${percent}%)</span>
                    </div>
                </div>`
            },
            backgroundColor: 'transparent',
            borderColor: 'transparent',
            borderWidth: 0,
            textStyle: { color: isDark ? '#fff' : '#000' },
            padding: 0,
            extraCssText: 'box-shadow: none;'
        },
        legend: {
            orient: 'horizontal',
            bottom: '25',
            left: 'center',
            itemGap: 15,
            itemWidth: 10,
            itemHeight: 10,
            icon: 'circle',
            formatter: (name: string) => {
                const connectivityItem = connectivityData.find(d => d.name === name)
                const tdsItem = tdsData.find(d => d.name === name)
                const value = connectivityItem?.value || tdsItem?.value || 0
                return `{n|${name}} {v|(${value})}`
            },
            textStyle: {
                rich: {
                    n: {
                        color: isDark ? '#94a3b8' : '#64748b',
                        fontSize: 11,
                        fontWeight: 500
                    },
                    v: {
                        color: isDark ? '#f8fafc' : '#0f172a',
                        fontSize: 11,
                        fontWeight: 700
                    }
                }
            }
        },
        series: [
            // Inner ring - TDS Status
            {
                name: 'TDS Status',
                type: 'pie',
                radius: ['35%', '52%'],
                center: ['50%', '45%'],
                avoidLabelOverlap: true,
                itemStyle: {
                    borderRadius: 10,
                    borderColor: isDark ? '#000' : '#fff',
                    borderWidth: 2,
                },
                label: { show: false },
                emphasis: {
                    itemStyle: {
                        shadowBlur: 20,
                        shadowColor: isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'
                    },
                    scale: true,
                    scaleSize: 5
                },
                data: tdsData.map(item => {
                    const isSafe = item.name === 'Safe TDS'
                    const baseColor = isSafe ? colorPalette.safeTDS : colorPalette.criticalTDS
                    return {
                        value: item.value,
                        name: item.name,
                        itemStyle: {
                            color: baseColor
                        }
                    }
                }),
                animationType: 'expansion',
                animationDuration: 1200,
                animationEasing: 'cubicOut'
            },
            // Outer ring - Connectivity Status
            {
                name: 'Connectivity',
                type: 'pie',
                radius: ['60%', '78%'],
                center: ['50%', '45%'],
                avoidLabelOverlap: true,
                itemStyle: {
                    borderRadius: 10,
                    borderColor: isDark ? '#000' : '#fff',
                    borderWidth: 2,
                },
                label: { show: false },
                emphasis: {
                    itemStyle: {
                        shadowBlur: 20,
                        shadowColor: isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'
                    },
                    scale: true,
                    scaleSize: 5
                },
                data: connectivityData.map(item => {
                    const isOnline = item.name === 'Online'
                    const baseColor = isOnline ? colorPalette.online : colorPalette.offline
                    return {
                        value: item.value,
                        name: item.name,
                        itemStyle: {
                            color: baseColor
                        }
                    }
                }),
                animationType: 'expansion',
                animationDuration: 1200,
                animationEasing: 'cubicOut',
                animationDelay: 400
            }
        ]
    }

    return (
        <ReactECharts
            option={option}
            style={{ height: '420px', width: '100%' }}
            opts={{ renderer: 'canvas' }}
            notMerge={true}
            lazyUpdate={true}
        />
    )
}

import { Component, type ErrorInfo, type ReactNode } from 'react'
import { db } from '../lib/firebase'
import { collection, addDoc, serverTimestamp } from 'firebase/firestore'

interface Props {
    children: ReactNode
}

interface State {
    hasError: boolean
}

export class ErrorBoundary extends Component<Props, State> {
    public state: State = {
        hasError: false
    }

    public static getDerivedStateFromError(_: Error): State {
        return { hasError: true }
    }

    public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
        console.error('Uncaught error:', error, errorInfo)

        // Log to Firestore
        addDoc(collection(db, 'frontend_errors'), {
            error: error.message,
            stack: errorInfo.componentStack,
            url: window.location.href,
            user_agent: navigator.userAgent,
            timestamp: serverTimestamp()
        }).catch((err) => {
            console.error('Failed to log error:', err)
        })
    }

    public render() {
        if (this.state.hasError) {
            return (
                <div className="min-h-screen flex items-center justify-center bg-background text-foreground p-4">
                    <div className="max-w-md w-full bg-card border border-border rounded-xl p-8 text-center shadow-2xl">
                        <h1 className="text-3xl font-bold text-red-500 mb-4">System Error</h1>
                        <p className="text-muted-foreground mb-6">
                            The application encountered a critical error. Our engineering team has been notified.
                        </p>
                        <button
                            onClick={() => window.location.reload()}
                            className="bg-primary hover:bg-primary/90 text-primary-foreground px-6 py-3 rounded-lg font-medium transition-colors"
                        >
                            Reload System
                        </button>
                    </div>
                </div>
            )
        }

        return this.props.children
    }
}

