                    </div>

                    <!-- Tail / Pointer -->
                    <div class="absolute -bottom-[10px] left-1/2 w-5 h-5"
                         style="background: ${isDark ? 'rgba(12, 12, 14, 0.9)' : 'rgba(255, 255, 255, 0.9)'}; 
