import { createContext, useContext, useState, useCallback, useEffect, useRef, type ReactNode } from 'react'
import type { EnrichedDevice } from '../types'
import { getDeviceDisplayName } from '../lib/constants'
import { db } from '../lib/firebase'
import { collection, addDoc, query, where, getDocs, updateDoc, limit, serverTimestamp } from 'firebase/firestore'

interface AlertContextValue {
    criticalDevices: EnrichedDevice[]
    setCriticalDevices: (devices: EnrichedDevice[]) => void
    alertCount: number
    clearAlerts: () => void
    getAlertMessages: () => { title: string; device: string; tds: number | undefined }[]
}

const AlertContext = createContext<AlertContextValue>({
    criticalDevices: [],
    setCriticalDevices: () => {},
    alertCount: 0,
    clearAlerts: () => {},
    getAlertMessages: () => [],
})

export function AlertProvider({ children }: { children: ReactNode }) {
    const [criticalDevices, setCriticalDevicesState] = useState<EnrichedDevice[]>([])
    // Track previous critical device IDs to detect recovery events
    const prevCriticalIds = useRef<Set<string>>(new Set())
    // Debounce timer ref
    const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

    const setCriticalDevices = useCallback((devices: EnrichedDevice[]) => {
        setCriticalDevicesState(devices)
    }, [])

    // Persist new critical alerts and auto-resolve recovered devices
    useEffect(() => {
        const currentCriticalIds = new Set(criticalDevices.map(d => d.id))

        // Find devices that recovered (were critical, now safe)
        const recoveredIds = [...prevCriticalIds.current].filter(id => !currentCriticalIds.has(id))

        // Auto-resolve alerts for recovered devices (frontend-side backup)
        const autoResolveRecovered = async () => {
            for (const deviceId of recoveredIds) {
                try {
                    const q = query(
                        collection(db, 'alerts'),
                        where('device_id', '==', deviceId),
                        where('status', '==', 'open'),
                        limit(10)
                    )
                    const snap = await getDocs(q)
                    for (const alertDoc of snap.docs) {
                        await updateDoc(alertDoc.ref, {
                            status: 'resolved',
                            resolved_at: new Date().toISOString(),
                            resolved_by: 'frontend_auto_recovery'
                        })
                    }
                    if (!snap.empty) {
                        console.log(`✅ Frontend auto-resolved ${snap.size} alert(s) for recovered device: ${deviceId}`)
                    }
                } catch (err) {
                    console.error('Error auto-resolving alert:', err)
                }
            }
        }

        // Debounced persist to prevent alert spam
        // NOTE: Server-side deduplication is the primary guard now.
        // This frontend persist is a backup for when checkSensorData Cloud Function
        // isn't triggered (e.g., data comes via ThingSpeak client-side polling only).
        const persistNewAlerts = async () => {
            for (const device of criticalDevices) {
                try {
                    // DEDUPLICATION: Check if an open alert already exists
                    const q = query(
                        collection(db, 'alerts'),
                        where('device_id', '==', device.id),
                        where('status', '==', 'open'),
                        limit(1)
                    )
                    const snap = await getDocs(q)
                    if (snap.empty) {
                        // Build alert message with context for potential data issues
                        const tdsValue = device.latest_tds ?? 0
                        const tempValue = device.latest_temperature ?? 0
                        const isUnusuallyHigh = tdsValue > 300

                        let message = `Critical TDS level detected: ${tdsValue} ppm`
                        if (isUnusuallyHigh) {
                            message += ` (Check sensor - unusually high reading, temp: ${tempValue}°C)`
                        }

                        await addDoc(collection(db, 'alerts'), {
                            device_id: device.id,
                            device_name: getDeviceDisplayName(device),
                            message: message,
                            severity: 'critical',
                            status: 'open',
                            created_at: new Date().toISOString(),
                            tds_value: device.latest_tds,
                            temp_value: device.latest_temperature,
                            timestamp: serverTimestamp()
                        })
                        console.log(`🚨 Alert logged for ${device.id}: ${message}`)

                        // Perfect Fit: Trigger haptic feedback for critical alerts
                        if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
                            navigator.vibrate([200, 100, 200]);
                        }
                    } else {
                        // Update existing alert with latest TDS value (keeps it fresh)
                        const existingDoc = snap.docs[0]
                        const tdsValue = device.latest_tds ?? 0
                        const tempValue = device.latest_temperature ?? 0
                        const isUnusuallyHigh = tdsValue > 300

                        let message = `Critical TDS level detected: ${tdsValue} ppm`
                        if (isUnusuallyHigh) {
                            message += ` (Check sensor - unusually high reading, temp: ${tempValue}°C)`
                        }

                        await updateDoc(existingDoc.ref, {
                            message: message,
                            tds_value: device.latest_tds,
                            temp_value: device.latest_temperature,
                            updated_at: new Date().toISOString()
                        })
                    }
                } catch (error) {
                    console.error('Error persisting alert:', error)
                }
            }
        }

        // Run auto-resolve immediately for recovered devices
        if (recoveredIds.length > 0) {
            autoResolveRecovered()
        }

        // Debounce the persist to prevent hammering Firestore
        if (criticalDevices.length > 0) {
            if (debounceTimer.current) clearTimeout(debounceTimer.current)
            debounceTimer.current = setTimeout(persistNewAlerts, 5000) // 5s debounce
        }

        // Update the previous IDs tracker
        prevCriticalIds.current = currentCriticalIds

        return () => {
            if (debounceTimer.current) clearTimeout(debounceTimer.current)
        }
    }, [criticalDevices])

    const clearAlerts = useCallback(() => {
        setCriticalDevicesState([])
    }, [])

    const getAlertMessages = useCallback(() => {
        return criticalDevices.map(d => ({
            title: 'Critical TDS Alert',
            device: getDeviceDisplayName(d),
            tds: d.latest_tds
        }))
    }, [criticalDevices])

    return (
        <AlertContext.Provider value={{
            criticalDevices,
            setCriticalDevices,
            alertCount: criticalDevices.length,
            clearAlerts,
            getAlertMessages
        }}>
            {children}
        </AlertContext.Provider>
    )
}

export function useAlerts() {
    return useContext(AlertContext)
}

import React, { createContext, useContext, useEffect, useState } from 'react'
import type { User } from 'firebase/auth'
import { onAuthStateChanged, signOut as firebaseSignOut } from 'firebase/auth'
import { doc, getDoc } from 'firebase/firestore'
import { auth, db } from '../lib/firebase'

export type Profile = {
    id: string
    email: string
    name?: string
    role: 'viewer' | 'field_engineer' | 'admin' | 'super_admin'
    avatar_url?: string
    created_at: string
}

type AuthContextType = {
    user: User | null
    profile: Profile | null
    loading: boolean
    isAdmin: boolean
    signOut: () => Promise<void>
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

export function AuthProvider({ children }: { children: React.ReactNode }) {
    const [user, setUser] = useState<User | null>(null)
    const [profile, setProfile] = useState<Profile | null>(null)
    const [loading, setLoading] = useState(true)
    const [adminEmails, setAdminEmails] = useState<string[]>([
        'adityadeole08@gmail.com',
        'ritik@evaratech.com',
        'yasha@evaratech.com',
        'aditya@evaratech.com'
    ])

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
            setUser(firebaseUser)
            
            if (firebaseUser) {
                await Promise.all([
                    fetchProfile(firebaseUser.uid, firebaseUser.email),
                    fetchAdminConfig()
                ])
            } else {
                setProfile(null)
                setLoading(false)
            }
        })

        return () => unsubscribe()
    }, [])

    async function fetchAdminConfig() {
        try {
            const configRef = doc(db, 'app_config', 'admin_emails')
            const configSnap = await getDoc(configRef)
            if (configSnap.exists()) {
                const data = configSnap.data()
                if (data.emails && Array.isArray(data.emails)) {
                    console.log('🛡️ Admin config loaded from Firestore')
                    setAdminEmails(data.emails.map((e: string) => e.toLowerCase()))
                }
            }
        } catch (err) {
            console.warn('⚠️ Failed to fetch admin config, using code fallbacks', err)
        }
    }

    async function fetchProfile(userId: string, email?: string | null) {
        try {
            const docRef = doc(db, 'users', userId)
            const docSnap = await getDoc(docRef)

            if (docSnap.exists()) {
                setProfile(docSnap.data() as Profile)
            } else if (email) {
                // Determine role: Use local admin list as source of truth for auto-profile
                const isHardcoded = adminEmails.includes(email.toLowerCase())
                const role = isHardcoded ? 'super_admin' : 'viewer'
                
                console.log(`🆕 Creating auto-profile for ${email} as ${role}`)
                
                const newProfile: Profile = {
                    id: userId,
                    email: email,
                    name: email.split('@')[0],
                    role: role as any,
                    created_at: new Date().toISOString()
                }
                
                setProfile(newProfile)
                
                import('firebase/firestore').then(({ setDoc, serverTimestamp }) => {
                    setDoc(docRef, {
                        ...newProfile,
                        created_at: serverTimestamp(),
                        status: 'active'
                    }, { merge: true }).catch(err => console.error('Auto-profile failed:', err))
                })
            } else {
                setProfile(null)
            }
        } catch (error) {
            console.error('Error fetching profile:', error)
        } finally {
            setLoading(false)
        }
    }

    const signOut = React.useCallback(async () => {
        await firebaseSignOut(auth)
    }, [])

    const isHardcodedAdmin = React.useMemo(() => 
        user?.email && adminEmails.includes(user.email.toLowerCase())
    , [user?.email, adminEmails])

    // SYNCHRONOUS DERIVED PROFILE: Ensures immediate Admin UI even if DB hangs
    const effectiveProfile = React.useMemo(() => {
        if (profile) return profile
        if (isHardcodedAdmin && user?.email) {
            return {
                id: user.uid,
                email: user.email,
                name: user.email.split('@')[0],
                role: 'super_admin' as const,
                created_at: new Date().toISOString(),
                status: 'active'
            }
        }
        return null
    }, [profile, isHardcodedAdmin, user])

    const authContextValue = React.useMemo(() => ({
        user,
        profile: effectiveProfile,
        loading: loading && !isHardcodedAdmin,
        isAdmin: isHardcodedAdmin || effectiveProfile?.role === 'admin' || effectiveProfile?.role === 'super_admin',
        signOut
    }), [user, effectiveProfile, loading, isHardcodedAdmin, signOut])

    return <AuthContext.Provider value={authContextValue}>{children}</AuthContext.Provider>
}

// eslint-disable-next-line react-refresh/only-export-components
export const useAuth = () => {
    const context = useContext(AuthContext)
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider')
    }
    return context
}

import React, { createContext, useContext, useState, useCallback, useEffect } from 'react'
import { db, messaging } from '../lib/firebase'
import { collection, addDoc, serverTimestamp, query, where, getDocs, limit } from 'firebase/firestore'
import { useAuth } from './AuthContext'
import { onMessage, getToken } from 'firebase/messaging'
import { toast } from 'sonner'

const VAPID_PUBLIC_KEY = (import.meta.env['VITE_VAPID_PUBLIC_KEY'] as string) || "";

interface NotificationContextType {
    soundEnabled: boolean
    toggleSound: () => void
    isSubscribed: boolean
    permission: NotificationPermission
    loading: boolean
    soundProfile: string
    setSoundProfile: (profile: string) => void
    playSound: (type?: 'success' | 'warning' | 'error') => void
    testSound: () => void
    testNotification: () => void
    subscribe: () => Promise<void>
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined)

export const useNotification = () => {
    const context = useContext(NotificationContext)
    if (!context) throw new Error('useNotification must be used within a NotificationProvider')
    return context
}

export const NotificationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { user } = useAuth()
    const [soundEnabled, setSoundEnabled] = useState(() => localStorage.getItem('alert-sound') !== 'false')
    const [soundProfile, setSoundProfileState] = useState(() => localStorage.getItem('alert-sound-profile') || 'classic')
    const [isSubscribed, setIsSubscribed] = useState(false)
    const [loading, setLoading] = useState(false)
    const [permission, setPermission] = useState<NotificationPermission>(
        typeof Notification !== 'undefined' ? Notification.permission : 'default'
    )

    const setSoundProfile = useCallback((profile: string) => {
        setSoundProfileState(profile)
        localStorage.setItem('alert-sound-profile', profile)
    }, [])

    const playSound = useCallback((type: 'success' | 'warning' | 'error' = 'success') => {
        if (!soundEnabled) return
        try {
            const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
            if (!AudioContextClass) return;
            const audioContext = new AudioContextClass();
            const oscillator = audioContext.createOscillator()
            const gainNode = audioContext.createGain()
            oscillator.connect(gainNode); gainNode.connect(audioContext.destination)
            const now = audioContext.currentTime

            if (soundProfile === 'modern') {
                oscillator.type = 'sine'
                if (type === 'error') {
                    oscillator.frequency.setValueAtTime(440, now); oscillator.frequency.exponentialRampToValueAtTime(110, now + 0.5)
                    gainNode.gain.setValueAtTime(0.3, now); gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.5)
                    oscillator.start(now); oscillator.stop(now + 0.5)
                } else {
                    oscillator.frequency.setValueAtTime(880, now); oscillator.frequency.exponentialRampToValueAtTime(440, now + 0.3)
                    gainNode.gain.setValueAtTime(0.2, now); gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.3)
                    oscillator.start(now); oscillator.stop(now + 0.3)
                }
            } else if (soundProfile === 'digital') {
                oscillator.type = 'square'
                if (type === 'error') {
                    oscillator.frequency.setValueAtTime(150, now); oscillator.frequency.setValueAtTime(100, now + 0.1)
                    gainNode.gain.value = 0.2
                    oscillator.start(now); oscillator.stop(now + 0.2)
                } else {
                    oscillator.frequency.setValueAtTime(1200, now); gainNode.gain.setValueAtTime(0.1, now)
                    gainNode.gain.setValueAtTime(0, now + 0.05)
                    oscillator.start(now); oscillator.stop(now + 0.05)
                }
            } else if (soundProfile === 'sonar') {
                oscillator.type = 'sine'; oscillator.frequency.setValueAtTime(2000, now)
                gainNode.gain.setValueAtTime(0.3, now); gainNode.gain.exponentialRampToValueAtTime(0.01, now + 1)
                oscillator.start(now); oscillator.stop(now + 1)
            } else {
                if (type === 'error') {
                    oscillator.type = 'square'; oscillator.frequency.setValueAtTime(1000, now)
                    oscillator.frequency.setValueAtTime(800, now + 0.1); oscillator.frequency.setValueAtTime(1000, now + 0.2)
                    gainNode.gain.value = 0.4; oscillator.start(now); oscillator.stop(now + 0.3)
                } else if (type === 'warning') {
                    oscillator.type = 'sine'; oscillator.frequency.value = 800; gainNode.gain.value = 0.3
                    oscillator.start(now); oscillator.stop(now + 0.2)
                } else {
                    oscillator.type = 'sine'; oscillator.frequency.setValueAtTime(600, now)
                    oscillator.frequency.linearRampToValueAtTime(800, now + 0.1); gainNode.gain.value = 0.2
                    oscillator.start(now); oscillator.stop(now + 0.15)
                }
            }
        } catch (err) { console.error('Failed to play sound:', err) }
    }, [soundEnabled, soundProfile])

    const testSound = useCallback(() => {
        playSound('success')
        toast.success('Sound Diagnostic', { description: `Profile "${soundProfile}" is playing correctly.` })
    }, [playSound, soundProfile])

    useEffect(() => {
        if (!messaging) return
        const unsubscribe = onMessage(messaging, (payload) => {
            console.log('🔔 Foreground Message:', payload)
            toast.error(payload.notification?.title || 'System Alert', {
                description: payload.notification?.body,
                duration: 5000,
                action: {
                    label: 'View',
                    onClick: () => {
                        window.focus()
                        if (payload.data?.url) window.location.href = payload.data.url
                    }
                }
            })
            playSound(payload.data?.severity === 'critical' ? 'error' : 'warning')
        })
        return () => unsubscribe()
    }, [playSound])

    const testNotification = useCallback(() => {
        if (typeof Notification !== 'undefined' && Notification.permission === 'granted') {
            new Notification('🔔 EvaraTDS Test Notification', {
                body: 'Your notification system is working correctly!',
                icon: '/pwa-192x192.png'
            })
        } else {
            toast('Notifications not granted', { description: 'Please subscribe/enable from settings.' })
        }
    }, [])

    const toggleSound = useCallback(() => {
        setSoundEnabled(prev => {
            const newValue = !prev
            localStorage.setItem('alert-sound', String(newValue))
            return newValue
        })
    }, [])

    useEffect(() => {
        const checkSubscription = async () => {
            if (!user || !messaging) return
            try {
                if ('serviceWorker' in navigator) {
                    const registration = await navigator.serviceWorker.ready
                    const subscription = await registration.pushManager.getSubscription()
                    setIsSubscribed(!!subscription)
                }
            } catch (err) {
                console.warn('Check subscription failed:', err)
            }
        }
        if (typeof Notification !== 'undefined') {
            setPermission(Notification.permission)
            checkSubscription()
        }
    }, [user])

    const subscribe = async () => {
        if (!user || !messaging) return
        if (typeof Notification === 'undefined') return

        if (Notification.permission === 'default') {
            const result = await Notification.requestPermission()
            setPermission(result)
            if (result !== 'granted') return
        }

        if (!VAPID_PUBLIC_KEY) {
            toast.error('VAPID Key Missing', { description: 'Contact admin to configure push keys.' })
            return
        }

        setLoading(true)
        try {
            // 1. Get FCM Token (Industry Grade)
            const token = await getToken(messaging, { vapidKey: VAPID_PUBLIC_KEY })

            if (!token) {
                throw new Error('No registration token available.')
            }

            // 2. DEDUPLICATION: Check if this token already exists for this user
            const q = query(
                collection(db, 'notification_subscriptions'),
                where('user_id', '==', user.uid),
                where('token', '==', token),
                limit(1)
            )
            const existing = await getDocs(q)

            if (existing.empty) {
                await addDoc(collection(db, 'notification_subscriptions'), {
                    user_id: user.uid,
                    token: token,
                    platform: 'web_pwa',
                    userAgent: navigator.userAgent,
                    created_at: serverTimestamp(),
                    last_seen_at: serverTimestamp()
                })
                setIsSubscribed(true)
                toast.success('Real-time alerts enabled!', { description: 'You will now receive push notifications.' })
            } else {
                setIsSubscribed(true)
                toast('Already subscribed', { description: 'This device is already configured for alerts.' })
            }
        } catch (error) {
            console.error('Subscription error:', error)
            toast.error('Subscription failed', { description: 'Please check your browser notification permissions.' })
        } finally {
            setLoading(false)
        }
    }

    return (
        <NotificationContext.Provider value={{
            soundEnabled, toggleSound, isSubscribed, permission, loading,
            subscribe, soundProfile, setSoundProfile, playSound, testSound, testNotification
        }}>
            {children}
        </NotificationContext.Provider>
    )
}

import React, { createContext, useContext, useEffect, useState } from 'react'
import { useViewport } from '../hooks/useViewport'

interface UIContextType {
    isMobile: boolean
    isTablet: boolean
    isDesktop: boolean
    isPWA: boolean
    isOffline: boolean
    toggleSidebar: () => void
    sidebarOpen: boolean
    inspectorDeviceId: string | null
    openInspector: (deviceId: string) => void
    closeInspector: () => void
}

const UIContext = createContext<UIContextType | undefined>(undefined)

export function UIProvider({ children }: { children: React.ReactNode }) {
    const [inspectorDeviceId, setInspectorDeviceId] = useState<string | null>(null)
    const [isPWA, setIsPWA] = useState(() => 
        typeof window !== 'undefined' && window.matchMedia('(display-mode: standalone)').matches
    )
    const [isOffline, setIsOffline] = useState(!navigator.onLine)
    const [sidebarOpen, setSidebarOpen] = useState(true) // Initialized to true, effect will sync if needed
    
    // Use unified viewport hook for consistent device detection
    const { isMobile, isTablet, isDesktop } = useViewport()

    useEffect(() => {
        const handleOffline = () => setIsOffline(true)
        const handleOnline = () => setIsOffline(false)

        // PWA Check - already handled in state initializer, but we can keep the listener if display-mode can change
        // (usually it doesn't change without reload, but for safety:)
        const pwaMedia = window.matchMedia('(display-mode: standalone)')
        const handlePWAMatch = (e: MediaQueryListEvent) => setIsPWA(e.matches)
        pwaMedia.addEventListener('change', handlePWAMatch)

        window.addEventListener('offline', handleOffline)
        window.addEventListener('online', handleOnline)

        return () => {
            window.removeEventListener('offline', handleOffline)
            window.removeEventListener('online', handleOnline)
            pwaMedia.removeEventListener('change', handlePWAMatch)
        }
    }, [])
    
    const [prevIsDesktop, setPrevIsDesktop] = useState(isDesktop)
    if (isDesktop !== prevIsDesktop) {
        setPrevIsDesktop(isDesktop)
        setSidebarOpen(isDesktop)
    }

    const toggleSidebar = React.useCallback(() => setSidebarOpen(prev => !prev), [])

    const openInspector = React.useCallback((deviceId: string) => setInspectorDeviceId(deviceId), [])
    const closeInspector = React.useCallback(() => setInspectorDeviceId(null), [])

    const uiContextValue = React.useMemo(() => ({
        isMobile,
        isTablet,
        isDesktop,
        isPWA,
        isOffline,
        toggleSidebar,
        sidebarOpen,
        inspectorDeviceId,
        openInspector,
        closeInspector
    }), [
        isMobile,
        isTablet,
        isDesktop,
        isPWA,
        isOffline,
        toggleSidebar,
        sidebarOpen,
        inspectorDeviceId,
        openInspector,
        closeInspector
    ])

    return (
        <UIContext.Provider value={uiContextValue}>
            {children}
        </UIContext.Provider>
    )
}

export const useUI = () => {
    const context = useContext(UIContext)
    if (context === undefined) {
        throw new Error('useUI must be used within a UIProvider')
    }
    return context
}

import { useEffect, useCallback, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'

interface KeyboardShortcut {
    key: string
    ctrlKey?: boolean
    shiftKey?: boolean
    altKey?: boolean
    action: () => void
    description: string
}

interface UseKeyboardShortcutsOptions {
    enabled?: boolean
}

export function useKeyboardShortcuts(options: UseKeyboardShortcutsOptions = {}) {
    const { enabled = true } = options
    const navigate = useNavigate()

    // Default shortcuts
    const shortcuts: KeyboardShortcut[] = useMemo(() => [
        {
            key: 'd',
            action: () => navigate('/'),
            description: 'Go to Dashboard'
        },
        {
            key: 'm',
            action: () => navigate('/map'),
            description: 'Go to Map'
        },
        {
            key: 'v',
            action: () => navigate('/devices'),
            description: 'Go to Devices'
        },
        {
            key: 'a',
            action: () => navigate('/alerts'),
            description: 'Go to Alerts'
        },
        {
            key: 's',
            action: () => navigate('/settings'),
            description: 'Go to Settings'
        },
        {
            key: '/',
            action: () => {
                // Focus search input if it exists
                const searchInput = document.querySelector('input[type="text"][placeholder*="Search"]') as HTMLInputElement
                if (searchInput) {
                    searchInput.focus()
                }
            },
            description: 'Focus Search'
        },
        {
            key: 'Escape',
            action: () => {
                // Close any open modals
                const closeButton = document.querySelector('[data-dismiss="modal"]') as HTMLButtonElement
                if (closeButton) {
                    closeButton.click()
                }
                // Blur focused element
                if (document.activeElement instanceof HTMLElement) {
                    document.activeElement.blur()
                }
            },
            description: 'Close Modal / Clear Focus'
        },
        {
            key: 'r',
            ctrlKey: false,
            shiftKey: true,
            action: () => {
                // Refresh current page data
                window.dispatchEvent(new CustomEvent('refresh-data'))
            },
            description: 'Refresh Data'
        }
    ], [navigate])

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (!enabled) return

        // Ignore if typing in an input
        const target = event.target as HTMLElement
        const isTyping = target.tagName === 'INPUT' ||
            target.tagName === 'TEXTAREA' ||
            target.isContentEditable

        // Allow some shortcuts even when typing
        const allowedWhileTyping = ['Escape']

        if (isTyping && !allowedWhileTyping.includes(event.key)) {
            return
        }

        // Find matching shortcut
        const shortcut = shortcuts.find(s =>
            s.key.toLowerCase() === event.key.toLowerCase() &&
            !!s.ctrlKey === event.ctrlKey &&
            !!s.shiftKey === event.shiftKey &&
            !!s.altKey === event.altKey
        )

        if (shortcut) {
            event.preventDefault()
            shortcut.action()
        }
    }, [enabled, shortcuts, navigate])

    useEffect(() => {
        document.addEventListener('keydown', handleKeyDown)
        return () => document.removeEventListener('keydown', handleKeyDown)
    }, [handleKeyDown])

    return { shortcuts }
}

// Keyboard shortcuts help component
export function KeyboardShortcutsHelp({ onClose }: { onClose: () => void }) {
    const { shortcuts } = useKeyboardShortcuts({ enabled: false })

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
            <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 max-w-md w-full mx-4">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-lg font-semibold text-white">Keyboard Shortcuts</h2>
                    <button
                        onClick={onClose}
                        className="text-slate-400 hover:text-white p-1"
                    >
                        ✕
                    </button>
                </div>
                <div className="space-y-2">
                    {shortcuts.map((shortcut, index) => (
                        <div key={index} className="flex items-center justify-between py-2 border-b border-slate-800 last:border-0">
                            <span className="text-slate-300 text-sm">{shortcut.description}</span>
                            <kbd className="px-2 py-1 bg-slate-800 rounded text-xs text-slate-400 font-mono">
                                {shortcut.ctrlKey && 'Ctrl + '}
                                {shortcut.shiftKey && 'Shift + '}
                                {shortcut.altKey && 'Alt + '}
                                {shortcut.key.toUpperCase()}
                            </kbd>
                        </div>
                    ))}
                </div>
                <p className="text-xs text-slate-500 mt-4 text-center">
                    Press <kbd className="px-1 bg-slate-800 rounded">?</kbd> to show this help
                </p>
            </div>
        </div>
    )
}

import { useQuery, useQueries } from '@tanstack/react-query'
import { type Device, type EnrichedDevice } from '../types'
import { fetchFeeds, fetchLastEntry, type FieldMapping, type ParsedSensorData } from '../lib/thingspeak'
import { queryKeys } from '../lib/queryClient'
import { cacheSensorData, getCachedSensorData } from '../lib/cache'
import { useEffect, useMemo } from 'react'
import { getConnectivityStatus } from '../lib/constants'

/**
 * Helper function to get field mapping from device
 */
function getFieldMapping(device: Device): FieldMapping {
    return {
        tds: device.tds_field_number || 1,
        temperature: device.temperature_field_number || 2,
        voltage: device.voltage_field_number || 3
    }
}

/**
 * Fetch ThingSpeak data for a single device
 */
async function fetchDeviceThingSpeakData(
    device: Device
): Promise<ParsedSensorData[]> {
    if (!device.thingspeak_channel_id || !device.thingspeak_read_key) {
        return []
    }

    // Use network-first strategy for real-time monitoring
    // Cache is used only as a fallback if network fails
    let cachedData: ParsedSensorData[] = []
    try {
        const cached = await getCachedSensorData(device.id)
        if (cached) {
            cachedData = cached
        }
    } catch (e) {
        console.warn('Cache read failed', e)
    }

    const mapping: FieldMapping = {
        tds: device.tds_field_number || 1,
        temperature: device.temperature_field_number || 2,
        voltage: device.voltage_field_number || 3
    }

    try {
        const data = await fetchFeeds(
            device.thingspeak_channel_id,
            device.thingspeak_read_key,
            mapping,
            2000 // Fetch last 2000 readings
        )

        // Cache the result for future offline use
        if (data.length > 0) {
            await cacheSensorData(device.id, data)
        }

        return data
    } catch (error) {
        console.warn(`Network fetch failed for ${device.id}, falling back to cache`)
        return cachedData
    }
}

/**
 * Hook to fetch ThingSpeak data for a single device
 * Optimized for real-time updates (1-2 second latency)
 */
export function useDeviceThingSpeakData(device: Device | undefined) {
    return useQuery({
        queryKey: queryKeys.sensorData(device?.id || ''),
        queryFn: () => fetchDeviceThingSpeakData(device!),
        enabled: !!device?.thingspeak_channel_id && !!device?.thingspeak_read_key,
        staleTime: 0, // Always consider stale - fetch immediately on mount/focus
        refetchInterval: 15 * 1000, // Poll every 15 seconds (respects ThingSpeak 4 req/sec free tier limit)
        refetchOnWindowFocus: true, // Refetch when user returns to tab
        refetchOnReconnect: true, // Refetch on network reconnect
        refetchIntervalInBackground: false, // Don't poll when tab is hidden (save resources)
        gcTime: 5 * 60 * 1000, // Keep in cache for 5 minutes
    })
}

/**
 * NEW: Hook to fetch ONLY the latest reading from ThingSpeak
 * Uses /last.json endpoint for maximum efficiency
 * 
 * Benefits:
 * - 100x less data transfer (200 bytes vs 20KB)
 * - Faster response time (1-2 seconds)
 * - Minimal API load
 * 
 * Use this for:
 * - Real-time device status
 * - Current TDS/temperature values
 * - Online/offline detection
 */
export function useDeviceLatestReading(device: Device | undefined) {
    return useQuery({
        queryKey: ['thingspeak', 'latest', device?.id || ''],
        queryFn: async () => {
            if (!device?.thingspeak_channel_id || !device?.thingspeak_read_key) {
                return null
            }

            const mapping = getFieldMapping(device)

            // Use /last.json endpoint for single latest entry
            const latestReading = await fetchLastEntry(
                device.thingspeak_channel_id,
                device.thingspeak_read_key,
                mapping
            )

            return latestReading
        },
        enabled: !!device?.thingspeak_channel_id && !!device?.thingspeak_read_key,
        staleTime: 0, // Always fresh
        refetchInterval: 15 * 1000, // Poll every 15 seconds (respects ThingSpeak free tier limit)
        refetchOnWindowFocus: true,
        refetchOnReconnect: true,
        refetchIntervalInBackground: false,
        gcTime: 5 * 60 * 1000,
    })
}

/**
 * Hook to fetch ThingSpeak data for multiple devices (batched)
 * Optimized: Only fetches the LATEST reading to enrich the device list.
 * This reduces data transfer by ~99% for large device lists.
 */
export function useAllDevicesThingSpeakData(devices: Device[]) {
    // Create queries for all devices - Optimized to only fetch LAST entry
    const queries = useQueries({
        queries: devices.map(device => ({
            queryKey: ['thingspeak', 'latest', device.id],
            queryFn: async () => {
                if (!device.thingspeak_channel_id || !device.thingspeak_read_key) {
                    return null
                }
                const mapping = getFieldMapping(device)
                return await fetchLastEntry(
                    device.thingspeak_channel_id,
                    device.thingspeak_read_key,
                    mapping
                )
            },
            enabled: !!device.thingspeak_channel_id && !!device.thingspeak_read_key,
            staleTime: 10 * 1000, 
            refetchInterval: 15 * 1000, 
            gcTime: 5 * 60 * 1000,
        }))
    })

    const enrichedDevices: EnrichedDevice[] = useMemo(() => {
        return devices.map((device, index) => {
            const query = queries[index]
            const latest = query.data
            
            return {
                ...device,
                latest_tds: latest?.tds,
                latest_temperature: latest?.temperature,
                latest_voltage: latest?.voltage,
                last_reading_at: latest?.timestamp,
                is_offline: getConnectivityStatus(latest?.timestamp) === 'offline'
            } as EnrichedDevice
        })
    }, [devices, queries])

    const isLoading = useMemo(() => queries.some(q => q.isLoading), [queries])
    const isError = useMemo(() => queries.some(q => q.isError), [queries])

    return useMemo(() => ({
        devices: enrichedDevices,
        isLoading,
        isError
    }), [enrichedDevices, isLoading, isError])
}

/**
 * Fetch ThingSpeak data for charts (real-time)
 * This provides high-frequency sensor data for real-time chart updates
 */
export function useDeviceThingSpeakChartData(
    device: Device | undefined,
    results: number = 100
) {
    return useQuery({
        queryKey: ['thingspeak_chart_data', device?.id, results],
        queryFn: async () => {
            if (!device?.thingspeak_channel_id || !device?.thingspeak_read_key) {
                return []
            }

            const mapping: FieldMapping = {
                tds: device.tds_field_number || 1,
                temperature: device.temperature_field_number || 2,
                voltage: device.voltage_field_number || 3
            }

            const data = await fetchFeeds(
                device.thingspeak_channel_id,
                device.thingspeak_read_key,
                mapping,
                results
            )

            return data
        },
        enabled: !!device?.thingspeak_channel_id && !!device?.thingspeak_read_key,
        staleTime: 10 * 1000, // 10 seconds for real-time feel
        refetchInterval: 15 * 1000, // Auto-refresh every 15 seconds
        gcTime: 60 * 1000
    })
}

/**
 * Log cache performance metrics
 */
export function useThingSpeakCacheMetrics() {
    useEffect(() => {
        const interval = setInterval(() => {
            // Log cache hit rate every minute
            console.log('📊 ThingSpeak Cache Metrics:', {
                timestamp: new Date().toISOString(),
                // Add more metrics as needed
            })
        }, 60 * 1000)

        return () => clearInterval(interval)
    }, [])
}

