import { openDB, type DBSchema, type IDBPDatabase } from 'idb'

interface EvaraTDSDB extends DBSchema {
    devices: {
        key: string
        value: {
            id: string
            data: any
            timestamp: number
        }
    }
    sensorData: {
        key: string
        value: {
            deviceId: string
            data: any[]
            timestamp: number
        }
    }
    metadata: {
        key: string
        value: {
            key: string
            value: any
            timestamp: number
        }
    }
}

const DB_NAME = 'evaratds-cache'
const DB_VERSION = 1
const CACHE_TTL = 24 * 60 * 60 * 1000 // 24 hours

let dbInstance: IDBPDatabase<EvaraTDSDB> | null = null

/**
 * Initialize IndexedDB
 */
export async function initDB(): Promise<IDBPDatabase<EvaraTDSDB>> {
    if (dbInstance) return dbInstance

    dbInstance = await openDB<EvaraTDSDB>(DB_NAME, DB_VERSION, {
        upgrade(db) {
            // Create object stores
            if (!db.objectStoreNames.contains('devices')) {
                db.createObjectStore('devices', { keyPath: 'id' })
            }
            if (!db.objectStoreNames.contains('sensorData')) {
                db.createObjectStore('sensorData', { keyPath: 'deviceId' })
            }
            if (!db.objectStoreNames.contains('metadata')) {
                db.createObjectStore('metadata', { keyPath: 'key' })
            }
        },
    })

    return dbInstance
}

/**
 * Store devices in IndexedDB
 */
export async function cacheDevices(devices: any[]): Promise<void> {
    const db = await initDB()
    const tx = db.transaction('devices', 'readwrite')

    await Promise.all([
        ...devices.map(device =>
            tx.store.put({
                id: device.id,
                data: device,
                timestamp: Date.now()
            })
        ),
        tx.done
    ])
}

/**
 * Get cached devices from IndexedDB
 */
export async function getCachedDevices(): Promise<any[] | null> {
    try {
        const db = await initDB()
        const allDevices = await db.getAll('devices')

        // Filter out stale data
        const now = Date.now()
        const validDevices = allDevices.filter(
            item => now - item.timestamp < CACHE_TTL
        )

        if (validDevices.length === 0) return null

        return validDevices.map(item => item.data)
    } catch (error) {
        console.error('Error reading cached devices:', error)
        return null
    }
}

/**
 * Store sensor data in IndexedDB
 */
export async function cacheSensorData(deviceId: string, data: any[]): Promise<void> {
    const db = await initDB()
    await db.put('sensorData', {
        deviceId,
        data,
        timestamp: Date.now()
    })
}

/**
 * Get cached sensor data from IndexedDB
 */
export async function getCachedSensorData(deviceId: string): Promise<any[] | null> {
    try {
        const db = await initDB()
        const cached = await db.get('sensorData', deviceId)

        if (!cached) return null

        // Check if stale
        if (Date.now() - cached.timestamp > CACHE_TTL) {
            return null
        }

        return cached.data
    } catch (error) {
        console.error('Error reading cached sensor data:', error)
        return null
    }
}

/**
 * Clear all cached data
 */
export async function clearCache(): Promise<void> {
    const db = await initDB()
    await Promise.all([
        db.clear('devices'),
        db.clear('sensorData'),
        db.clear('metadata')
    ])
}

/**
 * Get cache statistics
 */
export async function getCacheStats(): Promise<{
    deviceCount: number
    sensorDataCount: number
    totalSize: number
}> {
    const db = await initDB()
    const [devices, sensorData] = await Promise.all([
        db.getAll('devices'),
        db.getAll('sensorData')
    ])

    return {
        deviceCount: devices.length,
        sensorDataCount: sensorData.length,
        totalSize: devices.length + sensorData.length
    }
}

// System-wide constants for TDS monitoring and ThingSpeak integration

export const TDS_RANGES = {
    // User-visible safe range (Default)
    SAFE_MIN: 35,
    SAFE_MAX: 175,

    // Minimum valid reading (filter out sensor noise)
    MIN_VALID: 20,
    
    // Maximum valid reading (filter out voltage/temp misreads like 663)
    // Realistic TDS for drinking water should never exceed 500 ppm
    MAX_VALID: 500
} as const

// Calculate internal thresholds (Fallback)
export const TDS_THRESHOLDS = {
    CRITICAL_LOW: TDS_RANGES.SAFE_MIN,   // 35 ppm
    CRITICAL_HIGH: TDS_RANGES.SAFE_MAX   // 175 ppm
} as const

/**
 * Industrial IoT Heartbeat Detection Configuration
 * Based on best practices for real-time device monitoring
 */
export const HEARTBEAT_CONFIG = {
    // Expected heartbeat interval (devices send data every 15-30 seconds)
    EXPECTED_INTERVAL_MS: 30 * 1000,        // 30 seconds

    // Offline threshold: 1 hour (as per user request for industrial monitoring)
    OFFLINE_THRESHOLD_MS: 60 * 60 * 1000,    // 1 hour

    // Grace period before marking device as offline
    GRACE_PERIOD_MS: 30 * 1000,             // 30 seconds

    // Maximum time before device is considered stale
    STALE_THRESHOLD_MS: 5 * 60 * 1000       // 5 minutes
} as const

// Legacy constant for backward compatibility (now using HEARTBEAT_CONFIG)
export const OFFLINE_THRESHOLD_MS = HEARTBEAT_CONFIG.OFFLINE_THRESHOLD_MS

// 3 seconds for real-time monitoring (Phase 1: UI/UX Enhancement - faster updates)
export const THINGSPEAK_POLL_INTERVAL = 3000

/**
 * ThingSpeak API Configuration
 */
export const THINGSPEAK_CONFIG = {
    BASE_URL: 'https://api.thingspeak.com',
    RESULTS_LIMIT: 100, // Number of historical readings to fetch
    TIMEOUT: 10000      // API request timeout (10 seconds)
} as const

/**
 * Determine device status based on TDS value
 * Uses internal buffers for more accurate status determination
 */
export function getTDSStatus(
    tds: number | null | undefined, 
    customMin?: number, 
    customMax?: number
): 'online' | 'critical' | 'offline' {
    if (tds === null || tds === undefined) return 'offline'
    if (tds <= TDS_RANGES.MIN_VALID) return 'offline' // Invalid reading

    const min = customMin ?? TDS_THRESHOLDS.CRITICAL_LOW
    const max = customMax ?? TDS_THRESHOLDS.CRITICAL_HIGH

    if (tds < min || tds > max) {
        return 'critical'
    }
    
    return 'online'
}

/**
 * Check if a device is offline based on last reading timestamp
 * @deprecated Use getConnectivityStatus instead for dual categorization
 */
export function isDeviceOffline(lastReadingTime: string | null | undefined): boolean {
    if (!lastReadingTime) return true
    const lastReading = new Date(lastReadingTime).getTime()
    const now = Date.now()
    return (now - lastReading) > HEARTBEAT_CONFIG.OFFLINE_THRESHOLD_MS
}

/**
 * Filter valid TDS readings (exclude <= 20 ppm and >= 500 ppm)
 * Upper bound prevents false alerts from voltage/temp misreads (e.g., 663)
 */
export function isValidTDSReading(tds: number | null | undefined): boolean {
    return tds !== null && 
           tds !== undefined && 
           tds > TDS_RANGES.MIN_VALID && 
           tds < TDS_RANGES.MAX_VALID
}

/**
 * Categorize device based on TDS value (independent of connectivity)
 * A device can be offline but still have a TDS category based on last reading
 * Returns 'unknown' for values outside valid range (prevents false alerts)
 */
export function getTDSCategory(
    tds: number | null | undefined,
    customMin?: number,
    customMax?: number
): 'safe' | 'critical' | 'unknown' {
    if (tds === null || tds === undefined) return 'unknown'
    if (tds <= TDS_RANGES.MIN_VALID || tds >= TDS_RANGES.MAX_VALID) return 'unknown' // Invalid reading

    const min = customMin ?? TDS_THRESHOLDS.CRITICAL_LOW
    const max = customMax ?? TDS_THRESHOLDS.CRITICAL_HIGH

    // Critical if outside safe range
    if (tds < min || tds > max) {
        return 'critical'
    }

    // Safe if within range
    return 'safe'
}

/**
 * Industrial IoT Heartbeat Detection Algorithm
 * 
 * Determines connectivity status based on last reading timestamp.
 * 
 * Rules:
 * 1. Device is ONLINE if last_seen_at < 1 hour ago
 * 2. Device is OFFLINE if last_seen_at >= 1 hour ago
 * 
 * @param lastReadingTime - ISO timestamp of last reading
 * @returns 'online' | 'offline'
 */
export function getConnectivityStatus(lastReadingTime: string | null | undefined): 'online' | 'offline' {
    if (!lastReadingTime) return 'offline'

    try {
        // Ensure ISO format (replace space with T if needed)
        const normalized = lastReadingTime.includes(' ') && !lastReadingTime.includes('T') 
            ? lastReadingTime.replace(' ', 'T') 
            : lastReadingTime
            
        const lastReading = new Date(normalized).getTime()
        const now = Date.now()
        const msSinceLastReading = now - lastReading

        // Online if data received within the last 1 hour
        return msSinceLastReading < HEARTBEAT_CONFIG.OFFLINE_THRESHOLD_MS ? 'online' : 'offline'
    } catch (error) {
        return 'offline'
    }
}

/**
 * Type definitions for dual categorization
 */
export type TDSCategory = 'safe' | 'critical' | 'unknown'
export type ConnectivityStatus = 'online' | 'offline'

/**
 * Helper function to get device display name
 * Prefers location_name over device name
 */
export function getDeviceDisplayName(device: { location_name?: string | null; name: string }): string {
    return device.location_name || device.name || 'Unknown Device'
}

import { QueryClient } from '@tanstack/react-query'

/**
 * Optimized QueryClient configuration for EvaraTDS
 * 
 * Key features:
 * - 5 minute stale time (data considered fresh)
 * - 10 minute cache time (data kept in memory)
 * - Automatic refetching on window focus
 * - Exponential backoff retry strategy
 * - Request deduplication
 */
export const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            // Data is considered fresh for 5 minutes
            staleTime: 5 * 60 * 1000,

            // Keep unused data in cache for 10 minutes
            gcTime: 10 * 60 * 1000,

            // Refetch on window focus for real-time updates
            refetchOnWindowFocus: true,

            // Don't refetch on mount if data is fresh
            refetchOnMount: false,

            // Retry failed requests with exponential backoff
            retry: (failureCount, error: any) => {
                // Don't retry on 404 or 401
                if (error?.status === 404 || error?.status === 401) {
                    return false
                }
                // Max 3 retries
                return failureCount < 3
            },

            // Exponential backoff: 1s, 2s, 4s
            retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),

            // Enable request deduplication
            networkMode: 'online',
        },
        mutations: {
            // Retry mutations once
            retry: 1,

            // Network mode for mutations
            networkMode: 'online',
        },
    },
})

/**
 * Query keys for consistent cache management
 */
export const queryKeys = {
    // Devices
    devices: ['devices'] as const,
    device: (id: string) => ['devices', id] as const,

    // Sensor data
    sensorData: (deviceId: string) => ['sensor-data', deviceId] as const,
    allSensorData: ['sensor-data'] as const,

    // ThingSpeak
    thingspeakFeeds: (channelId: string) => ['thingspeak', 'feeds', channelId] as const,
    thingspeakLatest: (channelId: string) => ['thingspeak', 'latest', channelId] as const,

    // Aggregated stats
    dashboardStats: ['dashboard-stats'] as const,

    // Alerts
    alerts: ['alerts'] as const,
    activeAlerts: ['alerts', 'active'] as const,
    
    // Health Events
    healthEvents: (deviceId: string) => ['health-events', deviceId] as const,
}

/**
 * Prefetch data for faster navigation
 */
export async function prefetchDevices() {
    await queryClient.prefetchQuery({
        queryKey: queryKeys.devices,
        staleTime: 5 * 60 * 1000,
    })
}

/**
 * Invalidate all queries (force refetch)
 */
export function invalidateAllQueries() {
    queryClient.invalidateQueries()
}

/**
 * Clear all cached data
 */
export function clearQueryCache() {
    queryClient.clear()
}

